));gap:16px}.ui-screens-native{min-width:0}.ui-screens-native h4{margin:0 0 8px}.ui-screens-swap{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ui-screens-entry{display:flex;align-items:center;gap:8px;margin:8px 0}.ui-screens-grip{flex:none;min-width:24px;text-align:center;cursor:grab;touch-action:none;user-select:none}.ui-screens-name{flex:1;min-width:0;overflow-wrap:anywhere}.ui-screens-entry[data-dragging]{opacity:.5}.ui-screens-entry[data-over]{outline:thick solid var(--ui-accent,currentColor)}.ui-screens-checks li{display:flex;align-items:center;gap:8px;min-height:48px}.ui-screens-checks input{flex:none;width:24px;height:24px}.ui-screens-checks label{flex:1;min-width:0;min-height:48px;display:flex;align-items:center}.ui-screens-status{margin:8px 0;font-weight:600;overflow-wrap:anywhere}@media (prefers-reduced-motion:no-preference){.ui-screens-entry[data-new]{animation:ui-screens-in 180ms ease-out}}@keyframes ui-screens-in{from{opacity:0;transform:scaleY(0)}}}
