/* css/shell.css */
@layer components{.ui-shell{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;height:100vh;height:100dvh;min-width:0;background:var(--ui-bg);color:var(--ui-fg)}.ui-shell-radio{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}.ui-shell-icons{position:absolute;width:0;height:0;overflow:hidden}.ui-shell svg{width:24px;height:24px;flex:none;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.ui-shell-header{display:flex;align-items:center;gap:8px;min-height:56px;padding:0 8px;background:var(--ui-panel);border-bottom:1px solid var(--ui-border)}.ui-shell-title{flex:1;min-width:0;margin:0 8px;font-size:1.25rem;font-weight:400;line-height:1.25;overflow-wrap:anywhere}.ui-shell-actions{display:flex;align-items:center;gap:8px;flex:none}.ui-shell-actions .ui-input{padding:8px;max-width:128px}.ui-icon-button{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;padding:0;border-radius:50%;flex:none;cursor:pointer}.ui-icon-button[aria-pressed=true] svg{fill:currentColor}.ui-shell-body{display:flex;min-height:0}.ui-rail{display:none;flex-direction:column;gap:8px;width:80px;flex:none;padding:8px;border-right:1px solid var(--ui-border);background:var(--ui-panel);overflow:auto}.ui-rail-item,.ui-bottom-item{display:flex;align-items:center;gap:16px;min-height:48px;padding:0 16px;border-radius:var(--ui-radius);cursor:pointer}.ui-rail-label,.ui-bottom-label{font-size:.75rem}.ui-shell-main{flex:1;min-width:0;min-height:0;overflow-x:hidden;overflow-y:auto;padding:24px;overscroll-behavior:contain}.ui-shell-main h2{margin:0 0 16px;font-size:1.5rem;font-weight:400}.ui-shell-tags{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 24px}.ui-shell-cards{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(256px,1fr))}.ui-shell-card{display:flex;gap:16px;margin:0;min-width:0}.ui-shell-card h3{margin:0 0 8px;font