 accept="image/*" data-file><label class="ui-button" for="photo-file">Import image</label><button class="ui-button" type="button" data-paste>Paste photo</button><button class="ui-button" type="button" data-retry hidden>Retry</button><button class="ui-button" type="button" data-clear disabled>Clear photo</button></div><details class="ui-photo-help"><summary>How to edit</summary><p class="ui-muted">You can paste (Ctrl/Cmd+V) or drop an image anywhere on this panel. Choose a frame tool, then drag to make a frame. Drag inside a frame to move it; drag its corners or edges to resize. With the canvas focused: arrow keys move the selected frame (Shift for bigger steps), Delete removes it, Ctrl/Cmd+Z undoes.</p></details><div class="ui-photo-stagewrap"><canvas class="ui-photo-stage" data-stage width="760" height="280" tabindex="0" role="img" aria-label="Photo canvas"></canvas></div><fieldset class="ui-photo-bar"><legend>Frame tool</legend><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-shape-none" name="photo-shape" value="none" checked><label for="photo-shape-none">None</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-shape-rectangle" name="photo-shape" value="rectangle"><label for="photo-shape-rectangle">Rectangle</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-shape-circle" name="photo-shape" value="circle"><label for="photo-shape-circle">Circle</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-shape-triangle" name="photo-shape" value="triangle"><label for="photo-shape-triangle">Triangle</label></span></fieldset><fieldset class="ui-photo-bar"><legend>Frame colour</legend><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#7e57c2" name="photo-color" value="#7e57c2" checked><label for="photo-color-#7e57c2"><span class="ui-photo-dot ui-photo-c-purple"></span>Purple</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#e53935" name="photo-color" value="#e53935"><label for="photo-color-#e53935"><span class="ui-photo-dot ui-photo-c-red"></span>Red</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#43a047" name="photo-color" value="#43a047"><label for="photo-color-#43a047"><span class="ui-photo-dot ui-photo-c-green"></span>Green</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#1e88e5" name="photo-color" value="#1e88e5"><label for="photo-color-#1e88e5"><span class="ui-photo-dot ui-photo-c-blue"></span>Blue</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#fdd835" name="photo-color" value="#fdd835"><label for="photo-color-#fdd835"><span class="ui-photo-dot ui-photo-c-amber"></span>Amber</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#ffffff" name="photo-color" value="#ffffff"><label for="photo-color-#ffffff"><span class="ui-photo-dot ui-photo-c-white"></span>White</label></span><span class="ui-photo-choice"><input class="ui-photo-radio" type="radio" id="photo-color-#212121" name="photo-color" value="#212121"><label for="photo-color-#212121"><span class="ui-photo-dot ui-photo-c-black"></span>Black</label></span></fieldset><h3>Stamps</h3><div class="ui-photo-stamps"><button class="ui-button" type="button" data-stamp="⭐" aria-pressed="false" aria-label="Stamp ⭐">⭐</button><button class="ui-button" type="button" data-stamp="❤️" aria-pressed="false" aria-label="Stamp ❤️">❤️</button><button class="ui-button" type="button" data-stamp="😊" aria-pressed="false" aria-label="Stamp 😊">😊</button><button class="ui-button" type="button" data-stamp="🔥" aria-pressed="false" aria-label="Stamp 🔥">🔥</button><button class="ui-button" type="button" data-stamp="📷" aria-pressed="false" aria-label="Stamp 📷">📷</button><button class="ui-button" type="button" data-stamp="🌸" aria-pressed="false" aria-label="Stamp 🌸">🌸</button><button class="ui-button" type="button" data-stamp="✨" aria-pressed="false" aria-label="Stamp ✨">✨</button><button class="ui-button" type="button" data-stamp="🍀" aria-pressed="false" aria-label="Stamp 🍀">🍀</button></div><div class="ui-photo-stamps"><label for="photo-custom">Custom stamp</label><input class="ui-input" id="photo-custom" data-custom maxlength="12" placeholder="Emoji or short text" autocomplete="off"><button class="ui-button" type="button" data-arm aria-pressed="false">Arm stamp</button></div><div class="ui-photo-stamps"><label for="photo-scale">Stamp size</label><input type="range" id="photo-scale" data-scale min="0.4" max="3" step="0.1" value="1"> <output data-scale-out>1.0</output></div><div class="ui-photo-bar"><button class="ui-button" type="button" data-undo disabled>Undo</button><button class="ui-button" type="button" data-redo disabled>Redo</button><button class="ui-button" type="button" data-next>Select next frame</button><button class="ui-button" type="button" data-reset disabled>Reset selected frame</button><button class="ui-button" type="button" data-delete disabled>Delete frame</button></div><h3>Geometry</h3><pre class="ui-output" data-geometry>No frame selected.</pre><div class="ui-photo-bar"><button class="ui-button" type="button" data-copy-rect>Copy rectangle</button><button class="ui-button" type="button" data-copy-csv>Copy as CSV</button></div><div class="ui-photo-bar"><button class="ui-button" type="button" data-export>Save PNG</button><button class="ui-button" type="button" data-copy-b64-uri>Copy as Base64 (data URL)</button><button class="ui-button" type="button" data-copy-b64>Copy as Base64</button><button class="ui-button" type="button" data-share hidden>Share PNG</button></div><p class="ui-photo-live" role="status" aria-live="polite" data-live></p><details class="ui-photo-check"><summary>This browser</summary><p class="ui-muted">Tries to decode a few tiny pictures and reports what this browser can do, as JSON in the same shape as the Flutter app's import evidence. It measures this browser only; it is not a test of any other device.</p><button class="ui-button" type="button" data-check>Check this browser</button><pre class="ui-output" data-check-out></pre></details></section></main><script type="module">/* web-ui photo: the photo studio in the page (memory only). Format hints, header sizes, EXIF orientation, import rules, frame and stamp geometry, undo history and the editing state machine.
 The rules are Python's (web_ui.photo_sniff, photo_decide, PhotoStudio, ...); this must agree. Nothing is stored or sent. */
const MAX_IMAGE=32*1024*1024,IMAGE_TYPES=["image/png","image/jpeg","image/webp"];
const SPACE="\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
export const pyStrip=s=>s.replace(new RegExp("^["+SPACE+"]+|["+SPACE+"]+$","g"),"");
export const strip=s=>pyStrip(s.startsWith("\ufeff")?s.slice(1):s);
const B64=/^[A-Za-z0-9+/]*={0,2}$/,DATA=/^data:([a-z0-9.+-]+\/[a-z0-9.+-]+)?((?:;[a-z0-9.+-]+=[a-z0-9.+-]+)*);base64,/i;
export const shelfMaxChars=n=>4*Math.floor((n+2)/3);
export function sniffImageMime(b){return b.length>=8&&b[0]===0x89&&b[1]===0x50&&b[2]===0x4e&&b[3]===0x47&&b[4]===0x0d&&b[5]===0x0a&&b[6]===0x1a&&b[7]===0x0a?"image/png":b.length>=3&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff?"image/jpeg":
 b.length>=12&&b[0]===0x52&&b[1]===0x49&&b[2]===0x46&&b[3]===0x46&&b[8]===0x57&&b[9]===0x45&&b[10]===0x42&&b[11]===0x50?"image/webp":null}
export function decodeImageText(input,maxBytes=MAX_IMAGE){
 const fail=category=>({ok:false,category});let text=strip(input);if(!text)return fail("empty");
 let declared=null;const m=DATA.exec(text);
 if(m){declared=(m[1]||"").toLowerCase()||null;if(declared==="image/jpg")declared="image/jpeg";text=text.slice(m[0].length)}
 else if(text.slice(0,5).toLowerCase()==="data:")return fail("bad_data_uri");
 if(declared!==null&&!IMAGE_TYPES.includes(declared))return fail("unsupported_type");
 const encoded=text.replace(/[ \t\r\n\f\v]+/g,"");if(!encoded)return fail("empty");
 if(encoded.length>shelfMaxChars(maxBytes))return fail("too_large");
 if(encoded.length%4||!B64.test(encoded))return fail("bad_base64");
