/* css/matrix.css */
@layer components{.ui-matrix:has(>section:target)>section:not(:target){display:none}.ui-matrix>section{scroll-margin-top:16px}.ui-matrix-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--ui-matrix-col,160px),1fr));gap:var(--ui-matrix-gap,8px);padding:0;list-style:none}.ui-matrix-tiles li{border:1px solid var(--ui-border);padding:var(--ui-matrix-pad,8px);font-size:.8rem;overflow-wrap:anywhere}.ui-matrix-tiles img{display:block;width:100%;height:auto;margin:var(--ui-matrix-pad,8px) 0;background:#fff}.ui-matrix-tiles .is-missing{border-style:dashed;color:var(--ui-muted)}.ui-matrix-tiles .is-fail{outline:2px solid var(--ui-danger)}.ui-matrix-tiles .is-reference{outline:2px solid var(--ui-accent)}.ui-matrix-page>nav{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.ui-matrix-page>nav .ui-button{white-space:nowrap;text-decoration:none}.ui-matrix a{overflow-wrap:anywhere}}
/* css/mcp.css */
@layer components{.ui-mcp h3{margin:24px 0 8px}.ui-mcp label{display:block;margin:8px 0 4px}.ui-mcp .ui-input{width:100%;box-sizing:border-box}.ui-mcp textarea{min-height:96px;font-family:var(--ui-font-mono,monospace)}.ui-mcp-row{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-mcp pre{margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}.ui-mcp code{overflow-wrap:anywhere}.ui-mcp-status{margin:8px 0;font-weight:600}.ui-mcp-kind{display:flex;flex-wrap:wrap;gap:8px 16px;border:0;padding:0;margin:8px 0}.ui-mcp-kind label{display:inline-block;margin:0}}
/* css/patterns.css */
@layer components{.ui-patterns h3{margin:24px 0 8px}.ui-patterns label{display:block;margin:8px 0}.ui-patterns .ui-input{width:100%;box-sizing:border-box}.ui-patterns textarea{min-height:160px;font-family:var(--ui-font-mono,monospace)}.ui-patterns-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin:8px 0}.ui-patterns-bar label{display:inline-block;margin:0}.ui-patterns-bar .ui-input{width:auto;min-width:0;flex:1 1 128px}.ui-patterns-list{margin:8px 0;padding-left:24px;max-height:480px;overflow:auto}.ui-patterns-list li{margin:8px 0;overflow-wrap:anywhere}.ui-patterns pre{margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto}.ui-patterns-status{margin:8px 0;font-weight:600;overflow-wrap:anywhere}}
/* css/photo.css */
@layer components{.ui-photo h3{margin:24px 0 8px}.ui-photo-status{margin:8px 0 0;font-weight:600}.ui-photo-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0;padding:0;border:0}.ui-photo-bar legend{padding:0 0 4px}.ui-photo-radio,.ui-photo-file{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}.ui-photo-choice label{display:inline-flex;align-items:center;gap:8px;padding:4px 16px;border:1px solid var(--ui-border);border-radius:var(--ui-radius);cursor:pointer}.ui-photo-bar label.ui-button{cursor:pointer}.ui-photo-radio:checked+label{background:var(--ui-accent);color:var(--ui-bg)}.ui-photo-radio:focus-visible+label,.ui-photo-file:focus-visible+label{outline:2px solid var(--ui-fg);outline-offset:2px}.ui-photo-dot{display:inline-block;width:16px;height:16px;border:1px solid var(--ui-fg);border-radius:50%;background:var(--dot)}.ui-photo-c-purple{--dot:#7e57c2}.ui-photo-c-red{--dot:#e53935}.ui-photo-c-green{--dot:#43a047}.ui-photo-c-blue{--dot:#1e88e5}.ui-photo-c-amber{--dot:#fdd835}.ui-photo-c-white{--dot:#ffffff}.ui-photo-c-black{--dot:#212121}.ui-photo-stagewrap{margin:16px 0}.ui-photo-stage{display:block;max-width:100%;border:1px solid var(--ui-border);border-radius:var(--ui-radius);touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;cursor:crosshair}.ui-photo-stage:focus-visible{outline:2px solid var(--ui-accent);outline-offset:2px}.ui-photo-stamps{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-photo-stamps .ui-input{flex:1 1 128px;min-width:0}.ui-photo [aria-pressed="true"]{background:var(--ui-accent);color:var(--ui-bg)}.ui-photo pre{white-space:pre-wrap;overflow-wrap:anywhere}.ui-photo-live{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%)}.ui-photo details{margin:16px 0}.ui-photo summary{cursor:pointer;padding:8px 0}}
/* css/playground.css */
@layer components{.ui-play h3{margin:24px 0 8px}.ui-counter-value{font-size:3rem;line-height:1.1;margin:8px 0;font-variant-numeric:tabular-nums}.ui-counter-orbs{min-height:56px;font-size:28px;line-height:1.2;margin:8px 0;overflow-wrap:anywhere}.ui-counter-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-counter-bar label{display:inline-block;margin:0}.ui-counter-actions{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.ui-counter-history{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0;padding:0;list-style:none}.ui-counter-actions button,.ui-counter-history button{touch-action:manipulation}.ui-counter-orbs[data-playing]{animation:ui-orb-rise 700ms ease-out}@keyframes ui-orb-rise{from{opacity:.25;transform:translateY(0)}to{opacity:1;transform:translateY(-16px)}}.ui-irony-arena{position:relative;overflow:hidden;min-height:320px;margin:8px 0;border:1px solid var(--ui-border);border-radius:var(--ui-radius,12px);touch-action:pan-y}.ui-irony-card{position:absolute;left:50%;top:50%;translate:-50% -50%;transform:translate(var(--ox,0px),var(--oy,0px)) scale(var(--s,1));transition:transform 140ms ease-out;width:min(520px,calc(100% - 48px));margin:0;padding:8px 24px 28px;box-sizing:border-box;border:1px solid var(--ui-border);border-radius:var(--ui-radius,12px);background:var(--ui-panel);color:var(--ui-fg);box-shadow:0 2px 8px rgba(0,0,0,.2)}.ui-irony-card[data-dragging]{--s:1.035;transition:none;box-shadow:0 8px 24px rgba(0,0,0,.35)}.ui-irony-handle{display:block;width:48px;height:32px;margin:0 auto;border:0;background:none;color:inherit;font:inherit;line-height:32px;text-align:center;cursor:grab;touch-action:none}.ui-irony-handle:focus-visible{outline:2px solid currentColor;outline-offset:2px}.ui-irony-text{margin:8px 0 0;font-size:1.5rem;line-height:1.35;text-align:center;user-select:text;-webkit-user-select:text;overflow-wrap:anywhere}.ui-irony-tone{margin:8px 0 0;text-align:center}.ui-irony-arena[data-spawn]::after{content:"";position:absolute;left:50%;top:50%;width:80%;aspect-ratio:1;border:3px solid currentColor;border-radius:50%;transform:translate(-50%,-50%);animation:ui-irony-ring 850ms ease-out forwards;pointer-events:none}@keyframes ui-irony-ring{from{opacity:.55;scale:.15}to{opacity:0;scale:1}}@media(prefers-reduced-motion:reduce){.ui-counter-orbs[data-playing],.ui-irony-arena[data-spawn]::after{animation:none}.ui-irony-card{transition:none}}}
/* css/report.css */
