@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><section class="ui-panel ui-studio" id="studio" data-ui-studio><h2>Composition studio</h2><p class="ui-muted">Theory is computed from music rules, not stored. Python is the reference and this page gives the same answers.</p><h3>Metronome</h3><div class="ui-studio-row"><label for="studio-bpm">Tempo</label><input type="range" id="studio-bpm" min="30" max="300" value="120" data-bpm> <output data-bpm-out>120 BPM</output></div><fieldset class="ui-studio-bar"><legend>Time signature</legend><label><input type="radio" name="studio-sig" value="4/4" checked> 4/4</label><label><input type="radio" name="studio-sig" value="3/4"> 3/4</label><label><input type="radio" name="studio-sig" value="6/8"> 6/8</label></fieldset><div class="ui-beats" data-beats role="img" aria-label="Beat indicator"></div><p class="ui-muted" data-beat-info></p><div class="ui-studio-row"><button class="ui-button" type="button" data-run aria-pressed="false">Start</button><button class="ui-button" type="button" data-tap>Tap tempo</button></div><h3>Chord theory</h3><div class="ui-studio-row"><label for="studio-key">Key</label><select class="ui-input" id="studio-key" data-key><option value="C">C</option><option value="C♯">C♯</option><option value="D♭">D♭</option><option value="D">D</option><option value="D♯">D♯</option><option value="E♭">E♭</option><option value="E">E</option><option value="F">F</option><option value="F♯">F♯</option><option value="G♭">G♭</option><option value="G">G</option><option value="G♯">G♯</option><option value="A♭">A♭</option><option value="A">A</option><option value="A♯">A♯</option><option value="B♭">B♭</option><option value="B">B</option></select><button class="ui-button" type="button" data-semi-down>Semitone down</button><button class="ui-button" type="button" data-semi-up>Semitone up</button></div><fieldset class="ui-studio-bar"><legend>Mode</legend><label><input type="radio" name="studio-mode" value="Major" checked> Major</label><label><input type="radio" name="studio-mode" value="Minor"> Minor</label></fieldset><div class="ui-studio-row"><span>Circle of fifths</span><button class="ui-button" type="button" data-fifth-left></button><button class="ui-button" type="button" data-fifth-right></button></div><div class="ui-studio-degrees" data-degrees></div><div class="ui-studio-row"><label for="studio-prog">Progression (Roman numerals)</label><input class="ui-input" id="studio-prog" data-prog value="I V vi IV" autocomplete="off"></div><p class="ui-studio-chords" data-prog-out></p><div class="ui-studio-row"><label for="studio-degree">Chord builder</label><select class="ui-input" id="studio-degree" data-degree><option value="1">Degree 1</option><option value="2">Degree 2</option><option value="3">Degree 3</option><option value="4">Degree 4</option><option value="5">Degree 5</option><option value="6">Degree 6</option><option value="7">Degree 7</option></select><select class="ui-input" id="studio-mod" aria-label="Quality or extension" data-mod><option value="triad">triad</option><option value="6">6</option><option value="m6">m6</option><option value="7">7</option><option value="maj7">maj7</option><option value="m7">m7</option><option value="m7♭5">m7♭5</option><option value="sus2">sus2</option><option value="sus4">sus4</option><option value="add9">add9</option><option value="add11">add11</option><option value="dim">dim</option><option value="aug">aug</option></select></div><fieldset class="ui-studio-bar"><legend>Inversion</legend><label><input type="radio" name="studio-inv" value="0" checked> Root</label><label><input type="radio" name="studio-inv" value="1"> 1st</label><label><input type="radio" name="studio-inv" value="2"> 2nd</label><label><input type="radio" name="studio-inv" value="3"> 3rd</label></fieldset><p class="ui-studio-chords" data-chord></p><h3>Note sequence</h3><div class="ui-studio-row"><label for="studio-notes">Notes</label><select class="ui-input" id="studio-note-unit" aria-label="Note value" data-note-unit><option value="4">Quarter notes</option><option value="8" selected>Eighth notes</option></select></div><textarea class="ui-input" id="studio-notes" rows="2" data-notes>C3 D3 C3 D3 G3 A3 G3 C4</textarea><ol class="ui-studio-bars" data-bars></ol><h3>Song seed</h3><div class="ui-studio-row"><button class="ui-button" type="button" data-new-seed>New song seed</button></div><p class="ui-studio-chords" data-seed-out>Press the button for a key, tempo, time signature and progression.</p></section></main><script type="module">/* web-ui composition: chord theory, metronome timing, tap tempo, note sequences and a seeded song seed. Python (web_ui.chord_with_inversion, metronome_position, ...) is the reference. */
export const FLAT_KEYS=["C","D♭","D","E♭","E","F","G♭","G","A♭","A","B♭","B"],SHARP_KEYS=["C","C♯","D","D♯","E","F","F♯","G","G♯","A","A♯","B"];
export const SELECTABLE_KEYS=["C","C♯","D♭","D","D♯","E♭","E","F","F♯","G♭","G","G♯","A♭","A","A♯","B♭","B"];
export const CHORD_MODIFIERS=["triad","6","m6","7","maj7","m7","m7♭5","sus2","sus4","add9","add11","dim","aug"];
const MAJOR=[0,2,4,5,7,9,11],MINOR=[0,2,3,5,7,8,10],MAJOR_Q=["","m","m","","","m","dim"],MINOR_Q=["m","dim","","m","m","","" ],LETTERS="CDEFGAB",NAT={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
const INTERVALS={triad:[0,4,7],"6":[0,4,7,9],m6:[0,3,7,9],"7":[0,4,7,10],maj7:[0,4,7,11],m7:[0,3,7,10],"m7♭5":[0,3,6,10],sus2:[0,2,7],sus4:[0,5,7],add9:[0,4,7,14],add11:[0,4,7,17],dim:[0,3,6],dim7:[0,3,6,9],aug:[0,4,8]};
const ROMAN={I:1,II:2,III:3,IV:4,V:5,VI:6,VII:7},mod=(n,m)=>((n%m)+m)%m,trim=s=>s.replace(/^[ \t\r\n\f\v]+|[ \t\r\n\f\v]+$/g,"");
export function pitchClass(note){const m=typeof note==="string"?/^([A-G])([♯♭]*)$/.exec(note):null;if(!m)throw new Error("unsupported note: "+note);
 const sharps=(m[2].match(/♯/g)||[]).length,flats=(m[2].match(/♭/g)||[]).length;return mod(NAT[m[1]]+sharps-flats,12)}
