export function bindStudio(root=document){return[...root.querySelectorAll("[data-ui-studio]")].map(box=>{
 const $=s=>box.querySelector(s),$$=s=>[...box.querySelectorAll(s)],checked=n=>box.querySelector('input[name="'+n+'"]:checked').value;
