-size:1rem;font-weight:400}.ui-shell-card p{margin:0;overflow-wrap:anywhere}.ui-shell-table{width:100%;border-collapse:collapse}.ui-shell-table th,.ui-shell-table td{padding:8px 16px;border-bottom:1px solid var(--ui-border);text-align:left}.ui-shell-scroll{overflow-x:auto}.ui-shell-controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.ui-bottom-nav{display:flex;border-top:1px solid var(--ui-border);background:var(--ui-panel)}.ui-bottom-item{flex:1;flex-direction:column;justify-content:center;gap:0;min-height:64px;padding:8px 0;text-align:center}@media(min-width:900px){.ui-rail{display:flex}.ui-bottom-nav{display:none}.ui-rail-item{justify-content:center;padding:0}.ui-rail-label{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}}@media(min-width:1200px){.ui-rail{width:256px}.ui-rail-item{justify-content:flex-start;padding:0 16px}.ui-rail-label{position:static;width:auto;height:auto;margin:0;overflow:visible;clip-path:none;white-space:normal}}@media(max-height:480px){.ui-shell{height:auto;min-height:100dvh}.ui-shell-body{min-height:240px}.ui-shell-main{overflow:visible}}@media(prefers-reduced-motion:reduce){.ui-shell-main{scroll-behavior:auto}}}
/* css/stub.css */
@layer components{
.stub-shell{display:grid;gap:1rem}
/* Keep title/description and metadata side-by-side when space permits; wrap rather than compress either region. */
.stub-header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;flex-wrap:wrap}
.stub-toolbar{display:flex;gap:.5rem;flex-wrap:wrap}
.stub-toolbar fieldset{display:flex;gap:.5rem;align-items:end;flex-wrap:wrap;width:100%;border:0;padding:0;margin:0}
.stub-toolbar label{display:block}
.stub-toolbar .ui-input{flex:1 1 16rem}
.stub-status{margin:.75rem 0 0}
.stub-meta{display:flex;gap:.5rem;flex-wrap:wrap;margin:.75rem 0}
/* Primary result pane + secondary evidence/history sidebar. */
.stub-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(16rem,.45fr);gap:1rem}
.stub-result,.stub-evidence,.stub-history{min-width:0}
.stub-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--ui-border)}
.stub-endpoint{overflow-wrap:anywhere}
@media(max-width:720px){.stub-workspace{grid-template-columns:1fr}.stub-header{display:block}}
}
/* css/studio.css */
@layer components{.ui-studio h3{margin:24px 0 8px}.ui-studio label{display:inline-block;margin:8px 8px 4px 0}.ui-studio-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-studio-bar legend{padding:0 0 4px}.ui-studio-bar label{margin:0}.ui-studio-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-studio-row .ui-input{flex:1 1 192px;min-width:0}.ui-studio textarea.ui-input{width:100%;box-sizing:border-box}.ui-beats{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-beat{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border:1px solid var(--ui-border);border-radius:50%}.ui-beat[data-on]{background:var(--ui-accent);color:var(--ui-bg)}.ui-studio-bars{margin:8px 0;padding-left:24px}.ui-studio-bars li[data-error]{color:var(--ui-danger)}.ui-studio-chords{margin:8px 0;overflow-wrap:anywhere}.ui-studio-degrees{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}}
/* css/themes/github-like.css */
/* GitHub-like prioritizes familiar light GitHub visual cues while remaining a generic light theme. */
@layer theme{
body[data-ui-theme="github-like"]{
 --ui-bg:#ffffff;
 --ui-panel:#f6f8fa;
 --ui-fg:#1f2328;
 --ui-muted:#59636e;
 --ui-border:#d0d7de;
 --ui-accent:#0969da;
}
body[data-ui-theme="github-like"] .ui-panel,
body[data-ui-theme="github-like"] .ui-card{
 background:var(--ui-panel);
 border-radius:.375rem;
 box-shadow:none;
}
body[data-ui-theme="github-like"] .ui-button,
body[data-ui-theme="github-like"] .ui-input{
 background:#ffffff;
}
body[data-ui-theme="github-like"] .ui-title{
 border-bottom:1px solid var(--ui-border);
 padding-bottom:.5rem;
}
body[data-ui-theme="github-like"] .ui-tag{
 border-radius:999px;
 color:var(--ui-accent);
}
}
/* css/themes/modern.css */
@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><section class="ui-panel ui-mcp" id="mcp" data-ui-mcp><h2>MCP lab</h2><p class="ui-muted">In-page MCP server; nothing is sent. Legacy 2025-03-26 protocol (initialize and Mcp-Session-Id) and the current 2026-07-28 one (server/discover and per-request _meta).</p><p class="ui-muted" role="status" aria-live="polite" data-mcp-sessions></p><h3>Send a request</h3><p class="ui-muted">Pick a template, change what you like, send. Legacy requests after initialize need the session id (the template fills the last one).</p><div class="ui-mcp-row"><button class="ui-button" type="button" data-mcp-template="initialize">initialize</button> <button class="ui-button" type="button" data-mcp-template="initialized">notifications/initialized</button> <button class="ui-button" type="button" data-mcp-template="toolsList">tools/list</button> <button class="ui-button" type="button" data-mcp-template="toolsCall">tools/call (echo)</button> <button class="ui-button" type="button" data-mcp-template="discover">server/discover (2026-07-28)</button> <button class="ui-button" type="button" data-mcp-template="modernCall">tools/call (2026-07-28)</button> </div><label id="mcp-method-label" for="mcp-method">Method</label><select class="ui-input" id="mcp-method" data-mcp-method><option>POST</option><option>GET</option></select><label for="mcp-path">Path</label><input class="ui-input" id="mcp-path" data-mcp-path value="/mcp" autocomplete="off"><label for="mcp-headers">Headers (name: value, one per line)</label><textarea class="ui-input" id="mcp-headers" data-mcp-headers spellcheck="false" rows="3"></textarea><label for="mcp-body">Body</label><textarea class="ui-input" id="mcp-body" data-mcp-body spellcheck="false" rows="6"></textarea><p><button class="ui-button" type="button" data-mcp-send>Send</button> <button class="ui-button" type="button" data-mcp-reset>Reset the server</button></p><p class="ui-mcp-status" role="status" aria-live="polite" data-mcp-http-status>Nothing sent yet.</p><pre data-mcp-out-headers></pre><pre data-mcp-out-body></pre><h3>Run a demo</h3><label for="mcp-demo-text">Text to echo</label><input class="ui-input" id="mcp-demo-text" data-mcp-demo-text value="hello" autocomplete="off"><p><button class="ui-button" type="button" data-mcp-demo-legacy>Legacy echo demo</button> <button class="ui-button" type="button" data-mcp-demo-modern>Current echo demo</button></p><p class="ui-mcp-status" role="status" aria-live="polite" data-mcp-demo-status></p><ol data-mcp-demo-log></ol><h3>Header names</h3><p class="ui-muted">A name that is not plain printable ASCII travels as <code>=?base64?...?=</code>.</p><label for="mcp-codec">Name</label><input class="ui-input" id="mcp-codec" data-mcp-codec-in value="エコー" autocomplete="off"><pre data-mcp-codec-out></pre><h3>PKCE (RFC 7636, S256)</h3><label for="mcp-verifier">Code verifier</label><input class="ui-input" id="mcp-verifier" data-mcp-verifier value="dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk" autocomplete="off" spellcheck="false"><p>Challenge: <code data-mcp-challenge></code></p><p class="ui-muted">The value above is the verifier of the RFC's Appendix B; its challenge is <code>E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM</code>.</p><p><button class="ui-button" type="button" data-mcp-pkce-new>New verifier</button></p><h3>Bearer <redacted></h3><p class="ui-muted">Reads a JWT-shaped demo token (the signature is not checked).</p><label for="mcp-auth">Authorization header</label><input class="ui-input" id="mcp-auth" data-mcp-auth placeholder="Bearer <redacted>" autocomplete="off" spellcheck="false"><label for="mcp-aud">Expected audience</label><input class="ui-input" id="mcp-aud" data-mcp-aud value="http://127.0.0.1:8787/mcp" autocomplete="off"><p><button class="ui-button" type="button" data-mcp-auth-demo>Make a demo token (valid for an hour)</button></p><p class="ui-mcp-status" role="status" aria-live="polite" data-mcp-auth-out></p><h3>OAuth metadata</h3><fieldset class="ui-mcp-kind"><legend>Document</legend><label><input type="radio" name="mcp-meta-kind" value="server" checked> Authorization server</label><label><input type="radio" name="mcp-meta-kind" value="resource"> Protected resource</label></fieldset><label for="mcp-meta">JSON</label><textarea class="ui-input" id="mcp-meta" data-mcp-meta spellcheck="false" rows="8">{
 "issuer": "https://auth.example.test/",
 "authorization_endpoint": "https://auth.example.test/authorize",
 "token_endpoint": "https://auth.example.test/token",
 "response_types_supported": [
 "code"
 ],
 "code_challenge_methods_supported": [
 "S256"
 ],
 "scopes_supported": [
 "mcp"
 ]
}</textarea><pre data-mcp-meta-out></pre></section></main><script type="module">/* web-ui mcp: JSON-RPC, the dual-era MCP Streamable HTTP rules, an in-page server, a session client, OAuth metadata, PKCE and a Bearer <redacted> check (nothing is sent). Python (web_ui.McpFoundation, McpRoutes, McpClient, ...) is the reference; this must agree. */
const SHA_K=new Uint32Array([0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,
 0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,
 0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,
 0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>]);
export function sha256Bytes(input){const data=typeof input==="string"?new TextEncoder().encode(input):input,len=data.length,padded=new Uint8Array(((len+9+63)>>6)<<6);
