 page with a bridge that runs them).</p></section></main><script type="module">/* web-ui patterns: the pattern references of flutter_navigation_basic in the page (query, page, score's min-heap, reduce, workflow, transform, select, order, text, window, collection, structure) and the 792-pattern catalogue. Python (web_ui.pattern_*) is the reference; this must agree on every request, with the same refusal text. Three families (search, convert, validate) stay in Python: they lean on CPython's Unicode case folding, int parsing and urlsplit. JSON cannot tell 1 from 1.0 here: an integral number is an int, so a float written 1.0 reads as 1. */
const SHA_K=new Uint32Array([0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,
 0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,
 0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,
 0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>]);
export function sha256Bytes(input){const data=typeof input==="string"?new TextEncoder().encode(input):input,len=data.length,padded=new Uint8Array(((len+9+63)>>6)<<6);
 padded.set(data);padded[len]=0x80;const view=new DataView(padded.buffer),bits=len*8;view.setUint32(padded.length-8,Math.floor(bits/4294967296));view.setUint32(padded.length-4,bits>>>0);
 const H=new Uint32Array([0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>,0x<addr>]),W=new Uint32Array(64),rotr=(x,n)=>(x>>>n)|(x<<(32-n));
 for(let off=0;off<padded.length;off+=64){for(let i=0;i<16;i++)W[i]=view.getUint32(off+i*4);
 for(let i=16;i<64;i++){const a=W[i-15],b=W[i-2],s0=rotr(a,7)^rotr(a,18)^(a>>>3),s1=rotr(b,17)^rotr(b,19)^(b>>>10);W[i]=(W[i-16]+s0+W[i-7]+s1)>>>0}
 let a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
 for(let i=0;i<64;i++){const S1=rotr(e,6)^rotr(e,11)^rotr(e,25),ch=(e&f)^(~e&g),t1=(h+S1+ch+SHA_K[i]+W[i])>>>0,S0=rotr(a,2)^rotr(a,13)^rotr(a,22),maj=(a&b)^(a&c)^(b&c),t2=(S0+maj)>>>0;
 h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0}
 H[0]+=a;H[1]+=b;H[2]+=c;H[3]+=d;H[4]+=e;H[5]+=f;H[6]+=g;H[7]+=h}
 const out=new Uint8Array(32),o=new DataView(out.buffer);H.forEach((x,i)=>o.setUint32(i*4,x));return out}
export const sha256Hex=input=>Array.from(sha256Bytes(input),x=>x.toString(16).padStart(2,"0")).join("");
