function nativeInitial(n){
 if(has(NATIVE_STATE,String(n))){return["scope","model","atom"].includes(NATIVE_STATE[String(n)][0])?{left:0,right:0,rebuilds:{left:0,right:0}}:{count:0,notifications:0}}
