 let obj;
 try{const s=cursor.replace(/-/g,"+").replace(/_/g,"/"),padded=s+"=".repeat((4-s.length%4)%4);
 if(!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(padded))throw 0;
