const concurrencyLatency=job=>new Promise(resolve=>setTimeout(()=>resolve(job.value),job.delay));
async function concurrencyScheduled(jobs,limit){
 need(Number.isInteger(limit)&&limit>=1&&limit<=32,"concurrency 1..32");
