.stub-toolbar label{display:block}
.stub-toolbar .ui-input{flex:1 1 16rem}
.stub-status{margin:.75rem 0 0}
.stub-meta{display:flex;gap:.5rem;flex-wrap:wrap;margin:.75rem 0}
/* Primary result pane + secondary evidence/history sidebar. */
.stub-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(16rem,.45fr);gap:1rem}
.stub-result,.stub-evidence,.stub-history{min-width:0}
.stub-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--ui-border)}
.stub-endpoint{overflow-wrap:anywhere}
@media(max-width:720px){.stub-workspace{grid-template-columns:1fr}.stub-header{display:block}}
}
/* css/studio.css */
@layer components{.ui-studio h3{margin:24px 0 8px}.ui-studio label{display:inline-block;margin:8px 8px 4px 0}.ui-studio-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-studio-bar legend{padding:0 0 4px}.ui-studio-bar label{margin:0}.ui-studio-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-studio-row .ui-input{flex:1 1 192px;min-width:0}.ui-studio textarea.ui-input{width:100%;box-sizing:border-box}.ui-beats{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-beat{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border:1px solid var(--ui-border);border-radius:50%}.ui-beat[data-on]{background:var(--ui-accent);color:var(--ui-bg)}.ui-studio-bars{margin:8px 0;padding-left:24px}.ui-studio-bars li[data-error]{color:var(--ui-danger)}.ui-studio-chords{margin:8px 0;overflow-wrap:anywhere}.ui-studio-degrees{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}}
/* css/themes/github-like.css */
/* GitHub-like prioritizes familiar light GitHub visual cues while remaining a generic light theme. */
@layer theme{
body[data-ui-theme="github-like"]{
 --ui-bg:#ffffff;
 --ui-panel:#f6f8fa;
 --ui-fg:#1f2328;
 --ui-muted:#59636e;
 --ui-border:#d0d7de;
 --ui-accent:#0969da;
}
body[data-ui-theme="github-like"] .ui-panel,
body[data-ui-theme="github-like"] .ui-card{
 background:var(--ui-panel);
 border-radius:.375rem;
 box-shadow:none;
}
body[data-ui-theme="github-like"] .ui-button,
body[data-ui-theme="github-like"] .ui-input{
 background:#ffffff;
}
body[data-ui-theme="github-like"] .ui-title{
 border-bottom:1px solid var(--ui-border);
 padding-bottom:.5rem;
}
body[data-ui-theme="github-like"] .ui-tag{
 border-radius:999px;
 color:var(--ui-accent);
}
}
/* css/themes/modern.css */
@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><section class="ui-panel ui-imagestudio" id="imagestudio" data-ui-imagestudio><h2>Image studio</h2><p class="ui-muted">Layer shapes, text, photos and heatmaps. The scene stays in this page.</p><p class="ui-is-status" role="status" aria-live="polite" data-is="status">Starting.</p><div class="ui-is-board" data-is="board" tabindex="0" role="group" aria-label="Canvas: press to place or select, drag to move, arrow keys nudge"></div><div class="ui-is-bar"><button class="ui-button" type="button" data-is="undo" disabled>Undo</button><button class="ui-button" type="button" data-is="redo" disabled>Redo</button><button class="ui-button" type="button" data-is="blank">New canvas</button><output data-is="size">1280 × 720</output></div><h3 id="is-tools-title">Tools</h3><fieldset class="ui-is-bar"><legend>Press the canvas to place</legend><label><input type="radio" name="is-tool" value="select" checked> ↖ Select</label><label><input type="radio" name="is-tool" value="rect"> ▭ Rectangle</label><label><input type="radio" name="is-tool" value="ellipse"> ◯ Ellipse</label><label><input type="radio" name="is-tool" value="triangle"> △ Triangle</label><label><input type="radio" name="is-tool" value="text"> T Text</label><label><input type="radio" name="is-tool" value="stamp"> ✦ Stamp</label><label><input type="radio" name="is-tool" value="arrow"> → Arrow</label><label><input type="radio" name="is-tool" value="clock"> ◷ Clock</label></fieldset><div class="ui-is-layers"><button class="ui-button" type="button" data-stamp="❤️">❤️</button><button class="ui-button" type="button" data-stamp="😊">😊</button><button class="ui-button" type="button" data-stamp="🌱">🌱</button><button class="ui-button" type="button" data-stamp="📊">📊</button><button class="ui-button" type="button" data-stamp="✨">✨</button><button class="ui-button" type="button" data-stamp="📌">📌</button><button class="ui-button" type="button" data-stamp="🔰">🔰</button><button class="ui-button" type="button" data-stamp="(・∀・)">(・∀・)</button><button class="ui-button" type="button" data-stamp="(｡•̀ᴗ-)✧">(｡•̀ᴗ-)✧</button><button class="ui-button" type="button" data-stamp="٩(๑❛ᴗ❛๑)۶">٩(๑❛ᴗ❛๑)۶</button></div><p class="ui-muted" data-is="stampnote">Pick a stamp, then press the canvas.</p><label>Text or custom stamp<textarea class="ui-input" data-is="text" rows="2" spellcheck="false">Hello</textarea></label><div class="ui-is-bar"><label>Fill <input type="color" data-is="fill" value="#18a7a1"></label><label>Line <input type="color" data-is="stroke" value="#183c42"></label><label><input type="checkbox" data-is="outline"> Outline only</label><label>Clock time <input class="ui-input" type="time" data-is="clock" value="10:10"></label></div><h3>Layers</h3><div class="ui-is-layers" data-is="layers"></div><div class="ui-is-bar"><button class="ui-button" type="button" data-is="duplicate" disabled>Duplicate</button><button class="ui-button" type="button" data-is="delete" disabled>Delete</button><button class="ui-button" type="button" data-is="front" disabled>Forward</button><button class="ui-button" type="button" data-is="back" disabled>Backward</button><button class="ui-button" type="button" data-is="custom" disabled>Use as stamp</button></div><h3 data-is="selection">Select a layer</h3><div class="ui-is-grid"><label>X<input class="ui-input" type="number" data-is="x" disabled></label><label>Y<input class="ui-input" type="number" data-is="y" disabled></label><label>Width<input class="ui-input" type="number" data-is="w" disabled min="1"></label><label>Height<input class="ui-input" type="number" data-is="h" disabled min="1"></label><label>Rotation<input class="ui-input" type="number" data-is="rotation" disabled min="-360" max="360"></label><label>Opacity<input class="ui-input" type="number" data-is="opacity" disabled min="0" max="1" step="0.05"></label><label>Font size<input class="ui-input" type="number" data-is="fontsize" disabled min="4" max="512"></label></div><div class="ui-is-bar"><label>Font <select class="ui-input" data-is="fontfamily" disabled><option value="sans">Standard</option><option value="mono">Monospace (ASCII art)</option></select></label><label><input type="checkbox" data-is="mono" disabled> Draw text and images in one colour</label><label>Arrow head <select class="ui-input" data-is="arrowstyle" disabled><option value="beginner">🔰 in black</option><option value="triangle">Triangle</option></select></label><label>Head place <select class="ui-input" data-is="arrowplacement" disabled><option value="tip">Tip</option><option value="middle">Middle</option></select></label><label>Image scaling <select class="ui-input" data-is="sampling" disabled><option value="pixelated">Keep the dots</option><option value="smooth">Smooth</option></select></label></div><div class="ui-is-grid"><label>Mosaic cell <output data-is="cellout">1 px</output><input type="range" data-is="cell" min="1" max="128" value="1" disabled></label><label>Colour levels <output data-is="levelsout">256</output><input type="range" data-is="levels" min="2" max="256" value="256" disabled></label></div><div class="ui-is-bar"><label><input type="checkbox" data-is="labels" checked disabled> Number labels</label><button class="ui-button" type="button" data-is="continuous" disabled>Heatmap in continuous colour</button><button class="ui-button" type="button" data-is="apply" disabled>Apply text and colours</button></div><p class="ui-muted">Images are recomputed from the kept original; a mosaic never invents lost detail.</p><h3>Add</h3><div class="ui-is-bar"><label>Photo or image <input class="ui-is-file" type="file" accept="image/png,image/jpeg,image/webp" data-is="file"></label><button class="ui-button" type="button" data-is="paste">Paste an image</button></div><label>PNG, JPEG or WebP as Base64 or a data URI<textarea class="ui-input" data-is="b64in" rows="2" spellcheck="false"></textarea></label><div class="ui-is-bar"><button class="ui-button" type="button" data-is="b64import">Add the Base64 image</button></div><label>Numbers (rows, or a Plotly heatmap)<textarea class="ui-input" data-is="matrix" rows="2" spellcheck="false">[[0,1,2,3],[3,2,1,0],[1,null,2,3]]</textarea></label><div class="ui-is-bar"><button class="ui-button" type="button" data-is="heatmap">Add a heatmap</button><label>Matrix file <input class="ui-is-file" type="file" accept=".json,application/json" data-is="matrixfile"></label></div><h3>Canvas</h3><div class="ui-is-bar"><button class="ui-button" type="button" data-is="demo">Example: stamps and a heatmap</button><button class="ui-button" type="button" data-is="stampdemo">Example: clock, arrow, face</button></div><div class="ui-is-bar"><label>Background <input type="color" data-is="background" value="#f8f7f2"></label><label><input type="checkbox" data-is="transparent"> Transparent</label><label>Width <input class="ui-input" type="number" data-is="width" min="64" max="4096" value="1280"></label><label>Height <input class="ui-input" type="number" data-is="height" min="64" max="4096" value="720"></label><button class="ui-button" type="button" data-is="resize">Apply size</button></div><h3 id="is-export-title">Export</h3><div class="ui-is-bar"><label>Scale <select class="ui-input" data-is="scale"><option value="1">1×</option><option value="2">2×</option><option value="4">4×</option><option value="8">8×</option></select></label><button class="ui-button" type="button" data-is="svg">Save SVG</button><button class="ui-button" type="button" data-is="png">Save PNG</button><button class="ui-button" type="button" data-is="base64">PNG as Base64</button></div><details data-is="b64panel"><summary>Base64 for hand-off</summary><p class="ui-muted">The PNG as standard Base64. The image and the scene are not sent anywhere.</p><label>Form <select class="ui-input" data-is="b64mode"><option value="dataUri">PNG data URI</option><option value="base64">Base64 only</option></select></label><textarea class="ui-input" data-is="b64text" rows="6" readonly aria-label="Base64 image"></textarea><p class="ui-muted" role="status" data-is="b64status"></p><div class="ui-is-bar"><button class="ui-button" type="button" data-is="b64copy">Copy</button><button class="ui-button" type="button" data-is="b64save">Save as text</button></div></details><h3>Scene and history</h3><div class="ui-is-bar"><button class="ui-button" type="button" data-is="jsonsave">Save the scene as JSON</button><label>Open a scene <input class="ui-is-file" type="file" accept=".json,application/json" data-is="jsonopen"></label></div><div class="ui-is-bar"><button class="ui-button" type="button" data-is="wssave">Save the history</button><label>Open a history <input class="ui-is-file" type="file" accept=".json,application/json" data-is="wsopen"></label></div><details><summary>History (up to 40 states)</summary><ol class="ui-is-history" data-is="history" aria-label="History"></ol><button class="ui-button" type="button" data-is="trim">Keep only the current state</button><p class="ui-muted">A history file can hold your images. Check it before you share it.</p></details></section></main><script type="module">/* web-ui imagestudio: the Ironmate image studio in the page (memory only). Scene checks, SVG, history, workspace files and the layers a click places are the functions of web_ui.py (studio_*) and give the same text; the editor on top is the page's. Python is the reference; this must agree. Differences: text is measured with the installed fonts here (a fixed 0.65 em / 1 em estimate in Python), words and graphemes follow the same rules as Python (Latin, Hangul, kana and Han; the Japanese dictionary of Intl.Segmenter is not used, so every engine gives the same lines), and the clock hands use fdlibm's sin and cos written out here and in Python (V8's of Node 22), not the engine's Math.sin and Math.cos, which differ in the last bit between engines and versions. */
const MAX_IMAGE=32*1024*1024,IMAGE_TYPES=["image/png","image/jpeg","image/webp"];
const SPACE="\\t\\n\\v\\f\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
export const pyStrip=s=>s.replace(new RegExp("^["+SPACE+"]+|["+SPACE+"]+$","g"),"");
export const strip=s=>pyStrip(s.startsWith("\ufeff")?s.slice(1):s);
const B64=/^[A-Za-z0-9+/]*={0,2}$/,DATA=/^data:([a-z0-9.+-]+\/[a-z0-9.+-]+)?((?:;[a-z0-9.+-]+=[a-z0-9.+-]+)*);base64,/i;
export const shelfMaxChars=n=>4*Math.floor((n+2)/3);
export function sniffImageMime(b){return b.length>=8&&b[0]===0x89&&b[1]===0x50&&b[2]===0x4e&&b[3]===0x47&&b[4]===0x0d&&b[5]===0x0a&&b[6]===0x1a&&b[7]===0x0a?"image/png":b.length>=3&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff?"image/jpeg":
 b.length>=12&&b[0]===0x52&&b[1]===0x49&&b[2]===0x46&&b[3]===0x46&&b[8]===0x57&&b[9]===0x45&&b[10]===0x42&&b[11]===0x50?"image/webp":null}
export function decodeImageText(input,maxBytes=MAX_IMAGE){
 const fail=category=>({ok:false,category});let text=strip(input);if(!text)return fail("empty");
 let declared=null;const m=DATA.exec(text);
 if(m){declared=(m[1]||"").toLowerCase()||null;if(declared==="image/jpg")declared="image/jpeg";text=text.slice(m[0].length)}
 else if(text.slice(0,5).toLowerCase()==="data:")return fail("bad_data_uri");
 if(declared!==null&&!IMAGE_TYPES.includes(declared))return fail("unsupported_type");
 const encoded=text.replace(/[ \t\r\n\f\v]+/g,"");if(!encoded)return fail("empty");
 if(encoded.length>shelfMaxChars(maxBytes))return fail("too_large");
