/* css/stub.css */
@layer components{
.stub-shell{display:grid;gap:1rem}
/* Keep title/description and metadata side-by-side when space permits; wrap rather than compress either region. */
.stub-header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;flex-wrap:wrap}
.stub-toolbar{display:flex;gap:.5rem;flex-wrap:wrap}
.stub-toolbar fieldset{display:flex;gap:.5rem;align-items:end;flex-wrap:wrap;width:100%;border:0;padding:0;margin:0}
.stub-toolbar label{display:block}
.stub-toolbar .ui-input{flex:1 1 16rem}
.stub-status{margin:.75rem 0 0}
.stub-meta{display:flex;gap:.5rem;flex-wrap:wrap;margin:.75rem 0}
/* Primary result pane + secondary evidence/history sidebar. */
.stub-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(16rem,.45fr);gap:1rem}
.stub-result,.stub-evidence,.stub-history{min-width:0}
.stub-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--ui-border)}
.stub-endpoint{overflow-wrap:anywhere}
@media(max-width:720px){.stub-workspace{grid-template-columns:1fr}.stub-header{display:block}}
}
/* css/studio.css */
@layer components{.ui-studio h3{margin:24px 0 8px}.ui-studio label{display:inline-block;margin:8px 8px 4px 0}.ui-studio-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-studio-bar legend{padding:0 0 4px}.ui-studio-bar label{margin:0}.ui-studio-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-studio-row .ui-input{flex:1 1 192px;min-width:0}.ui-studio textarea.ui-input{width:100%;box-sizing:border-box}.ui-beats{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-beat{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border:1px solid var(--ui-border);border-radius:50%}.ui-beat[data-on]{background:var(--ui-accent);color:var(--ui-bg)}.ui-studio-bars{margin:8px 0;padding-left:24px}.ui-studio-bars li[data-error]{color:var(--ui-danger)}.ui-studio-chords{margin:8px 0;overflow-wrap:anywhere}.ui-studio-degrees{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}}
/* css/themes/github-like.css */
/* GitHub-like prioritizes familiar light GitHub visual cues while remaining a generic light theme. */
@layer theme{
body[data-ui-theme="github-like"]{
  --ui-bg:#ffffff;
  --ui-panel:#f6f8fa;
  --ui-fg:#1f2328;
  --ui-muted:#59636e;
  --ui-border:#d0d7de;
  --ui-accent:#0969da;
}
body[data-ui-theme="github-like"] .ui-panel,
body[data-ui-theme="github-like"] .ui-card{
  background:var(--ui-panel);
  border-radius:.375rem;
  box-shadow:none;
}
body[data-ui-theme="github-like"] .ui-button,
body[data-ui-theme="github-like"] .ui-input{
  background:#ffffff;
}
body[data-ui-theme="github-like"] .ui-title{
  border-bottom:1px solid var(--ui-border);
  padding-bottom:.5rem;
}
body[data-ui-theme="github-like"] .ui-tag{
  border-radius:999px;
  color:var(--ui-accent);
}
}
/* css/themes/modern.css */
@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><h1 class="ui-title">web-ui</h1><p class="ui-muted">Shared static UI contract for myon-bioinformatics projects.</p><section class="ui-grid"><article class="ui-card"><h2>Components</h2><p>Tokens, panels, cards, tags, controls and output surfaces.</p><span class="ui-tag">modern</span> <span class="ui-tag">static</span></article><article class="ui-card"><h2>Stub examples</h2><p><a href="./mcp-stub.html">MCP Stub</a> · <a href="./api-stub.html">API Stub</a></p></article><article class="ui-card"><h2>Themes</h2><p><a href="./github-like.html">GitHub-like theme</a></p></article><article class="ui-card"><h2>App shell</h2><p><a href="./showcase.html">Showcase</a>: header, rail or bottom bar, sections.</p></article><article class="ui-card"><h2>Clipboard shelf</h2><p><a href="./clipboard-shelf.html">Shelf and prompt workbench</a>: paste, filter, copy a bundle.</p></article><article class="ui-card"><h2>Door-to-Door</h2><p><a href="./door.html">Pull-down and emoji transitions</a>: A → B, A ↔ B.</p></article><article class="ui-card"><h2>Composition studio</h2><p><a href="./composition-studio.html">Metronome, chords, notes, song seed</a>.</p></article><article class="ui-card"><h2>Play studio</h2><p><a href="./play-studio.html">Counter garden and Irony quest</a>.</p></article><article class="ui-card"><h2>Timeline</h2><p><a href="./timeline.html">Dated events in UTC order</a>.</p></article><article class="ui-card"><h2>Coordinates</h2><p><a href="./coordinates.html">Check a point, read a Maps URL, frame an area</a>.</p></article><article class="ui-card"><h2>Photo studio</h2><p><a href="./photo-studio.html">Frames and stamps on a photo, EXIF-safe import, PNG export</a>.</p></article><article class="ui-card"><h2>Playground</h2><p><a href="./playground.html">A counter with a history, a hold-to-repeat button, and a draggable irony card</a>.</p></article><article class="ui-card"><h2>Test report</h2><p><a href="./test-report.html">Read a JUnit report or Flutter test events; what is new, recurring or resolved</a>.</p></article><article class="ui-card"><h2>MCP lab</h2><p><a href="./mcp-lab.html">An MCP server in the page: both protocol eras, PKCE, header names, Bearer and OAuth metadata</a>.</p></article><article class="ui-card"><h2>792 patterns</h2><p><a href="./patterns.html">The flutter_navigation_basic catalogue and the processing behind it: filter, sort, page, validate, convert, workflow</a>.</p></article><article class="ui-card"><h2>198 screens</h2><p><a href="./screens.html">The Hub and every numbered screen of flutter_navigation_basic in eleven languages, and its native examples: counters, drag to reorder or swap, insert, select, a sum in a Web Worker</a>.</p></article><article class="ui-card"><h2>Image studio</h2><p><a href="./image-studio.html">Layer shapes, text, photos and heatmaps; export SVG, PNG or Base64; keep the history</a>.</p></article></section></main></body></html>
', 'examples/mcp-stub.html': '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MCP Stub</title><style>@layer base,components,theme;
/* css/tokens.css */
:root{--ui-bg:#0d1117;--ui-panel:#101820;--ui-fg:#d1f7c4;--ui-muted:#8b949e;--ui-border:#58a6ff;--ui-accent:#7ee787;--ui-danger:#cf222e;--ui-radius:0;--ui-space:1rem;--ui-max:960px;--ui-font:Meiryo,メイリオ,sans-serif;--ui-font-mono:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace}
/* Candidate themes, token-only: palettes, no theme files (see theme_palettes()). */
body[data-ui-theme="green"]{--ui-bg:#edf0ec;--ui-panel:#ffffff;--ui-fg:#163b3b;--ui-muted:#546a61;--ui-border:#ccdcd4;--ui-accent:#126d66;--ui-danger:#a73528;--ui-radius:.5rem;color-scheme:light}
body[data-ui-theme="red"]{--ui-bg:#f6eeee;--ui-panel:#fdfcfc;--ui-fg:#6c4141;--ui-muted:#7e6363;--ui-border:#d4bfbf;--ui-accent:#c43131;--ui-danger:#d02525;--ui-radius:.5rem;color-scheme:light}
body[data-ui-theme="blue"]{--ui-bg:#eef1f6;--ui-panel:#fcfcfd;--ui-fg:#41526c;--ui-muted:#636e7e;--ui-border:#bfc7d4;--ui-accent:#316cc4;--ui-danger:#d02525;--ui-radius:.5rem;color-scheme:light}
/* css/base.css */
@layer base{*{box-sizing:border-box}body{margin:0;background:var(--ui-bg);color:var(--ui-fg);font:16px/1.6 var(--ui-font)}pre,code,kbd,samp{font-family:var(--ui-font-mono)!important}.ui-page{max-width:var(--ui-max);margin:auto;padding:1.25rem}a{color:inherit}}
/* css/components.css */
@layer components{.ui-panel,.ui-card{background:var(--ui-panel);border:1px solid var(--ui-border);padding:1rem;margin:1rem 0;border-radius:var(--ui-radius)}.ui-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.75rem}.ui-tag{display:inline-block;border:1px solid var(--ui-border);padding:.1rem .4rem}.ui-button,.ui-input{font:inherit;background:var(--ui-panel);color:var(--ui-fg);border:1px solid var(--ui-border);padding:.6rem;border-radius:var(--ui-radius)}.ui-muted{color:var(--ui-muted)}.ui-output{font:inherit;white-space:pre-wrap;overflow:auto;background:#d8dee4;color:#161b22;border:1px solid #8c959f;border-radius:4px;padding:.75rem}pre code,.ui-output code{font-family:inherit;color:inherit}pre.ui-output code{background:transparent}@media(max-width:480px){.ui-page{padding:.75rem}.ui-grid{grid-template-columns:1fr}.ui-card,.ui-panel{margin:.75rem 0;padding:.75rem}}.ui-lightbox{border:1px solid var(--ui-border);background:var(--ui-panel);color:var(--ui-fg);padding:1rem;max-width:min(96vw,960px);max-height:96vh;border-radius:var(--ui-radius)}.ui-lightbox::backdrop{background:rgba(0,0,0,.72)}.ui-lightbox img{display:block;max-width:100%;max-height:calc(96vh - 8rem);margin:auto}.ui-lightbox-bar{display:flex;gap:.5rem;justify-content:space-between;margin-top:.75rem}body:has(.ui-lightbox[open]){overflow:hidden}}
/* css/coordinates.css */
@layer components{.ui-coord label{display:block;margin:8px 0 4px}.ui-coord .ui-input{width:100%;box-sizing:border-box}.ui-coord-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-coord-bar label{display:inline-block;margin:0}.ui-coord dt{margin:16px 0 4px}.ui-coord dd{margin:0}.ui-coord dd pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}}
/* css/door.css */
@layer components{.ui-door label{display:block;margin:8px 0 4px}.ui-door-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.ui-door-row .ui-input{flex:1 1 256px;min-width:0}.ui-door>.ui-input{width:100%;box-sizing:border-box}.ui-door-path{margin:8px 0;padding-left:24px}.ui-door-path a{overflow-wrap:anywhere}}
/* css/imagestudio.css */
@layer components{.ui-imagestudio h3{margin:24px 0 8px}.ui-imagestudio label{display:block;margin:8px 0}.ui-imagestudio textarea{width:100%;box-sizing:border-box;font-family:var(--ui-font-mono,monospace)}.ui-imagestudio .ui-input{max-width:100%;box-sizing:border-box}.ui-is-status{margin:8px 0;font-weight:600;overflow-wrap:anywhere}.ui-imagestudio[data-error] .ui-is-status{color:var(--ui-danger)}.ui-is-board{position:relative;width:100%;max-width:1280px;overflow:hidden;line-height:0;border:thin solid var(--ui-border);touch-action:pan-y;background:conic-gradient(#fff 25%,#d8d8d8 0 50%,#fff 0 75%,#d8d8d8 0) 0 0/16px 16px}.ui-is-board[data-capture]{touch-action:none}.ui-is-board svg{display:block;width:100%;height:auto}.ui-is-board:focus-visible{outline:medium solid var(--ui-accent);outline-offset:8px}.ui-is-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-is-bar legend{padding:0 0 8px}.ui-is-bar label,.ui-is-bar .ui-input{display:inline-flex;flex-wrap:wrap;align-items:center;gap:8px;margin:0;min-width:0;max-width:100%}.ui-is-bar .ui-input{width:auto}.ui-is-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(104px,1fr));gap:0 16px}.ui-is-grid>*{min-width:0}.ui-is-grid input[type=number]{width:100%}.ui-imagestudio input[type=range]{width:100%;min-width:0;box-sizing:border-box}.ui-is-layers{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-is-layers button[aria-pressed=true]{background:var(--ui-accent);color:var(--ui-bg)}.ui-imagestudio input[type=color]{width:48px;height:40px;padding:0}.ui-is-history{margin:8px 0;padding-left:24px}.ui-is-history li{margin:8px 0}.ui-is-file{max-width:100%;min-width:0}.ui-imagestudio details{margin:8px 0}.ui-imagestudio details summary{cursor:pointer}}
/* css/matrix.css */
@layer components{.ui-matrix:has(>section:target)>section:not(:target){display:none}.ui-matrix>section{scroll-margin-top:16px}.ui-matrix-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--ui-matrix-col,160px),1fr));gap:var(--ui-matrix-gap,8px);padding:0;list-style:none}.ui-matrix-tiles li{border:1px solid var(--ui-border);padding:var(--ui-matrix-pad,8px);font-size:.8rem;overflow-wrap:anywhere}.ui-matrix-tiles img{display:block;width:100%;height:auto;margin:var(--ui-matrix-pad,8px) 0;background:#fff}.ui-matrix-tiles .is-missing{border-style:dashed;color:var(--ui-muted)}.ui-matrix-tiles .is-fail{outline:2px solid var(--ui-danger)}.ui-matrix-tiles .is-reference{outline:2px solid var(--ui-accent)}.ui-matrix-page>nav{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.ui-matrix-page>nav .ui-button{white-space:nowrap;text-decoration:none}.ui-matrix a{overflow-wrap:anywhere}}
/* css/mcp.css */
@layer components{.ui-mcp h3{margin:24px 0 8px}.ui-mcp label{display:block;margin:8px 0 4px}.ui-mcp .ui-input{width:100%;box-sizing:border-box}.ui-mcp textarea{min-height:96px;font-family:var(--ui-font-mono,monospace)}.ui-mcp-row{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-mcp pre{margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}.ui-mcp code{overflow-wrap:anywhere}.ui-mcp-status{margin:8px 0;font-weight:600}.ui-mcp-kind{display:flex;flex-wrap:wrap;gap:8px 16px;border:0;padding:0;margin:8px 0}.ui-mcp-kind label{display:inline-block;margin:0}}
/* css/patterns.css */
@layer components{.ui-patterns h3{margin:24px 0 8px}.ui-patterns label{display:block;margin:8px 0}.ui-patterns .ui-input{width:100%;box-sizing:border-box}.ui-patterns textarea{min-height:160px;font-family:var(--ui-font-mono,monospace)}.ui-patterns-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin:8px 0}.ui-patterns-bar label{display:inline-block;margin:0}.ui-patterns-bar .ui-input{width:auto;min-width:0;flex:1 1 128px}.ui-patterns-list{margin:8px 0;padding-left:24px;max-height:480px;overflow:auto}.ui-patterns-list li{margin:8px 0;overflow-wrap:anywhere}.ui-patterns pre{margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto}.ui-patterns-status{margin:8px 0;font-weight:600;overflow-wrap:anywhere}}
/* css/photo.css */
@layer components{.ui-photo h3{margin:24px 0 8px}.ui-photo-status{margin:8px 0 0;font-weight:600}.ui-photo-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0;padding:0;border:0}.ui-photo-bar legend{padding:0 0 4px}.ui-photo-radio,.ui-photo-file{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}.ui-photo-choice label{display:inline-flex;align-items:center;gap:8px;padding:4px 16px;border:1px solid var(--ui-border);border-radius:var(--ui-radius);cursor:pointer}.ui-photo-bar label.ui-button{cursor:pointer}.ui-photo-radio:checked+label{background:var(--ui-accent);color:var(--ui-bg)}.ui-photo-radio:focus-visible+label,.ui-photo-file:focus-visible+label{outline:2px solid var(--ui-fg);outline-offset:2px}.ui-photo-dot{display:inline-block;width:16px;height:16px;border:1px solid var(--ui-fg);border-radius:50%;background:var(--dot)}.ui-photo-c-purple{--dot:#7e57c2}.ui-photo-c-red{--dot:#e53935}.ui-photo-c-green{--dot:#43a047}.ui-photo-c-blue{--dot:#1e88e5}.ui-photo-c-amber{--dot:#fdd835}.ui-photo-c-white{--dot:#ffffff}.ui-photo-c-black{--dot:#212121}.ui-photo-stagewrap{margin:16px 0}.ui-photo-stage{display:block;max-width:100%;border:1px solid var(--ui-border);border-radius:var(--ui-radius);touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;cursor:crosshair}.ui-photo-stage:focus-visible{outline:2px solid var(--ui-accent);outline-offset:2px}.ui-photo-stamps{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-photo-stamps .ui-input{flex:1 1 128px;min-width:0}.ui-photo [aria-pressed="true"]{background:var(--ui-accent);color:var(--ui-bg)}.ui-photo pre{white-space:pre-wrap;overflow-wrap:anywhere}.ui-photo-live{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%)}.ui-photo details{margin:16px 0}.ui-photo summary{cursor:pointer;padding:8px 0}}
/* css/playground.css */
@layer components{.ui-play h3{margin:24px 0 8px}.ui-counter-value{font-size:3rem;line-height:1.1;margin:8px 0;font-variant-numeric:tabular-nums}.ui-counter-orbs{min-height:56px;font-size:28px;line-height:1.2;margin:8px 0;overflow-wrap:anywhere}.ui-counter-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-counter-bar label{display:inline-block;margin:0}.ui-counter-actions{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.ui-counter-history{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0;padding:0;list-style:none}.ui-counter-actions button,.ui-counter-history button{touch-action:manipulation}.ui-counter-orbs[data-playing]{animation:ui-orb-rise 700ms ease-out}@keyframes ui-orb-rise{from{opacity:.25;transform:translateY(0)}to{opacity:1;transform:translateY(-16px)}}.ui-irony-arena{position:relative;overflow:hidden;min-height:320px;margin:8px 0;border:1px solid var(--ui-border);border-radius:var(--ui-radius,12px);touch-action:pan-y}.ui-irony-card{position:absolute;left:50%;top:50%;translate:-50% -50%;transform:translate(var(--ox,0px),var(--oy,0px)) scale(var(--s,1));transition:transform 140ms ease-out;width:min(520px,calc(100% - 48px));margin:0;padding:8px 24px 28px;box-sizing:border-box;border:1px solid var(--ui-border);border-radius:var(--ui-radius,12px);background:var(--ui-panel);color:var(--ui-fg);box-shadow:0 2px 8px rgba(0,0,0,.2)}.ui-irony-card[data-dragging]{--s:1.035;transition:none;box-shadow:0 8px 24px rgba(0,0,0,.35)}.ui-irony-handle{display:block;width:48px;height:32px;margin:0 auto;border:0;background:none;color:inherit;font:inherit;line-height:32px;text-align:center;cursor:grab;touch-action:none}.ui-irony-handle:focus-visible{outline:2px solid currentColor;outline-offset:2px}.ui-irony-text{margin:8px 0 0;font-size:1.5rem;line-height:1.35;text-align:center;user-select:text;-webkit-user-select:text;overflow-wrap:anywhere}.ui-irony-tone{margin:8px 0 0;text-align:center}.ui-irony-arena[data-spawn]::after{content:"";position:absolute;left:50%;top:50%;width:80%;aspect-ratio:1;border:3px solid currentColor;border-radius:50%;transform:translate(-50%,-50%);animation:ui-irony-ring 850ms ease-out forwards;pointer-events:none}@keyframes ui-irony-ring{from{opacity:.55;scale:.15}to{opacity:0;scale:1}}@media(prefers-reduced-motion:reduce){.ui-counter-orbs[data-playing],.ui-irony-arena[data-spawn]::after{animation:none}.ui-irony-card{transition:none}}}
/* css/report.css */
@layer components{.ui-report h3{margin:24px 0 8px}.ui-report label{display:block;margin:8px 0 4px}.ui-report .ui-input{width:100%;box-sizing:border-box}.ui-report textarea{min-height:96px;font-family:var(--ui-font-mono,monospace)}.ui-report-line{margin:8px 0;font-weight:600;overflow-wrap:anywhere}.ui-report-check{display:inline-block!important;margin:0 0 0 8px!important}.ui-report table{border-collapse:collapse;width:100%}.ui-report th,.ui-report td{border:1px solid var(--ui-border);padding:4px 8px;text-align:left;vertical-align:top;overflow-wrap:anywhere}.ui-report-status{margin:8px 0}.ui-report code{overflow-wrap:anywhere}.ui-report-more{margin:8px 0}}
/* css/repository-diagnostics.css */
.repo-diagnostics{box-sizing:border-box;border:1px solid var(--ui-border,#c9c9cf);border-radius:1rem;padding:1.25rem;background:var(--ui-surface,#fff);color:var(--ui-text,#222)}.repo-diagnostics h2{margin:0 0 .75rem;font-size:1.25rem}.repo-diagnostics__commit{overflow-wrap:anywhere}.repo-diagnostics__measurements{display:grid;grid-template-columns:minmax(8rem,1fr) 1fr;gap:.45rem 1rem;margin:1rem 0 0}.repo-diagnostics__measurements dt,.repo-diagnostics__measurements dd{margin:0}.repo-diagnostics__measurements dd{font-variant-numeric:tabular-nums}@media(max-width:30rem){.repo-diagnostics__measurements{grid-template-columns:1fr}.repo-diagnostics__measurements dd{margin-bottom:.35rem}}
/* css/screens.css */
@layer components{.ui-screens h3{margin:24px 0 8px}.ui-screens-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin:8px 0}.ui-screens .ui-button,.ui-screens select,.ui-screens .ui-input{min-height:48px;box-sizing:border-box;max-width:100%}.ui-screens-bar .ui-input{width:auto;min-width:0}@media(max-width:480px){.ui-screens-bar{gap:4px 8px}}.ui-screens-stage{min-width:0;margin:16px 0}.ui-screens-stage input[type=search],.ui-screens-stage #screens-field{width:100%}.ui-screens-items,.ui-screens-list,.ui-screens-checks,.ui-screens-chips,.ui-screens-links,.ui-screens-grid,.ui-screens-reorder,.ui-screens-swap,.ui-screens-animated{list-style:none;margin:8px 0;padding:0}.ui-screens-items{display:grid;gap:8px}.ui-screens-items[data-mode=grid]{grid-template-columns:repeat(auto-fill,minmax(160px,1fr))}.ui-screens-item{display:grid;gap:8px;min-height:48px;text-decoration:none;color:inherit;overflow-wrap:anywhere}.ui-screens-emoji{font-size:24px}.ui-screens-chips{display:flex;flex-wrap:wrap;gap:8px}.ui-screens-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ui-screens-grid li{white-space:pre-line;text-align:center}.ui-screens-list li{display:flex;gap:16px;align-items:center;margin:8px 0}.ui-screens-avatar{display:inline-flex;align-items:center;justify-content:center;flex:none;width:40px;height:40px;border-radius:50%;background:var(--ui-accent,currentColor);color:var(--ui-bg,Canvas)}.ui-screens-tabs,.ui-screens-bottom{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-screens-tabs [aria-selected=true],.ui-screens-bottom [aria-current=page]{font-weight:700;text-decoration:underline}.ui-screens-dialog{margin:16px 0}.ui-screens code,.ui-screens-links li{overflow-wrap:anywhere}.ui-screens [data-screens-count]{display:block}.ui-screens pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;font-family:var(--ui-font-mono,monospace)}.ui-screens-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}.ui-screens-native{min-width:0}.ui-screens-native h4{margin:0 0 8px}.ui-screens-swap{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ui-screens-entry{display:flex;align-items:center;gap:8px;margin:8px 0}.ui-screens-grip{flex:none;min-width:24px;text-align:center;cursor:grab;touch-action:none;user-select:none}.ui-screens-name{flex:1;min-width:0;overflow-wrap:anywhere}.ui-screens-entry[data-dragging]{opacity:.5}.ui-screens-entry[data-over]{outline:thick solid var(--ui-accent,currentColor)}.ui-screens-checks li{display:flex;align-items:center;gap:8px;min-height:48px}.ui-screens-checks input{flex:none;width:24px;height:24px}.ui-screens-checks label{flex:1;min-width:0;min-height:48px;display:flex;align-items:center}.ui-screens-status{margin:8px 0;font-weight:600;overflow-wrap:anywhere}@media (prefers-reduced-motion:no-preference){.ui-screens-entry[data-new]{animation:ui-screens-in 180ms ease-out}}@keyframes ui-screens-in{from{opacity:0;transform:scaleY(0)}}}
/* css/shelf.css */
