@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
@layer components{#showcase:has(#showcase-sec-overview:checked) .ui-shell-section:not([data-section="overview"]){display:none}#showcase:has(#showcase-sec-overview:checked) label[for="showcase-sec-overview"]{background:var(--ui-accent);color:var(--ui-bg)}#showcase:has(#showcase-sec-overview:focus-visible) label[for="showcase-sec-overview"]{outline:2px solid var(--ui-fg);outline-offset:2px}#showcase:has(#showcase-sec-components:checked) .ui-shell-section:not([data-section="components"]){display:none}#showcase:has(#showcase-sec-components:checked) label[for="showcase-sec-components"]{background:var(--ui-accent);color:var(--ui-bg)}#showcase:has(#showcase-sec-components:focus-visible) label[for="showcase-sec-components"]{outline:2px solid var(--ui-fg);outline-offset:2px}#showcase:has(#showcase-sec-data:checked) .ui-shell-section:not([data-section="data"]){display:none}#showcase:has(#showcase-sec-data:checked) label[for="showcase-sec-data"]{background:var(--ui-accent);color:var(--ui-bg)}#showcase:has(#showcase-sec-data:focus-visible) label[for="showcase-sec-data"]{outline:2px solid var(--ui-fg);outline-offset:2px}#showcase:has(#showcase-sec-media:checked) .ui-shell-section:not([data-section="media"]){display:none}#showcase:has(#showcase-sec-media:checked) label[for="showcase-sec-media"]{background:var(--ui-accent);color:var(--ui-bg)}#showcase:has(#showcase-sec-media:focus-visible) label[for="showcase-sec-media"]{outline:2px solid var(--ui-fg);outline-offset:2px}}</style></head><body data-ui-theme="modern"><div class="ui-shell" id="showcase"><svg class="ui-shell-icons" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><symbol id="showcase-icon-components" viewBox="0 0 24 24"><path d="M3 3h6v6H3ZM3 15h6v6H3ZM15 15h6v6h-6ZM17 2l5 5-5 5-5-5Z"/></symbol><symbol id="showcase-icon-data" viewBox="0 0 24 24"><path d="M3 4h18v16H3ZM3 9h18M9 9v11M15 9v11"/></symbol><symbol id="showcase-icon-layers" viewBox="0 0 24 24"><path d="m12 3 9 7-9 7-9-7Zm-9 12 9 7 9-7"/></symbol><symbol id="showcase-icon-media" viewBox="0 0 24 24"><path d="M3 4h18v16H3Zm2 13 5-6 4 4 2-2 3 4"/></symbol><symbol id="showcase-icon-overview" viewBox="0 0 24 24"><path d="M3 3h7v9H3ZM14 3h7v5h-7ZM3 16h7v5H3ZM14 12h7v9h-7Z"/></symbol><symbol id="showcase-icon-responsive" viewBox="0 0 24 24"><path d="M3 5h18v14H3ZM16 5v14M16 12h5"/></symbol><symbol id="showcase-icon-star" viewBox="0 0 24 24"><path d="m12 3 2.8 6 6.5.8-4.8 4.5 1.3 6.5-5.8-3.3-5.8 3.3 1.3-6.5L2.7 9.8 9.2 9Z"/></symbol><symbol id="showcase-icon-tune" viewBox="0 0 24 24"><path d="M3 6h10m4 0h4M3 12h4m4 0h10M3 18h12m4 0h2M13 3v6M7 9v6M15 15v6"/></symbol></svg><input class="ui-shell-radio" type="radio" name="showcase-section" id="showcase-sec-overview" value="overview" checked><input class="ui-shell-radio" type="radio" name="showcase-section" id="showcase-sec-components" value="components"><input class="ui-shell-radio" type="radio" name="showcase-section" id="showcase-sec-data" value="data"><input class="ui-shell-radio" type="radio" name="showcase-section" id="showcase-sec-media" value="media"><header class="ui-shell-header"><h1 class="ui-shell-title">🎨 UI Showcase</h1><div class="ui-shell-actions"><select class="ui-input" data-ui-theme-switch aria-label="Theme"><option value="modern">modern</option><option value="github-like">github-like</option><option value="green">green</option><option value="red">red</option><option value="blue">blue</option></select><button class="ui-button ui-icon-button" type="button" data-ui-toggle aria-pressed="false" aria-label="Favorite this page" title="Favorite this page" data-label-off="Favorite this page" data-label-on="Remove from favorites"><svg aria-hidden="true"><use href="#showcase-icon-star"/></svg></button></div></header><div class="ui-shell-body"><nav class="ui-rail" aria-label="Sections"><label class="ui-rail-item" for="showcase-sec-overview"><svg aria-hidden="true"><use href="#showcase-icon-overview"/></svg><span class="ui-rail-label">Overview</span></label><label class="ui-rail-item" for="showcase-sec-components"><svg aria-hidden="true"><use href="#showcase-icon-components"/></svg><span class="ui-rail-label">Components</span></label><label class="ui-rail-item" for="showcase-sec-data"><svg aria-hidden="true"><use href="#showcase-icon-data"/></svg><span class="ui-rail-label">Data</span></label><label class="ui-rail-item" for="showcase-sec-media"><svg aria-hidden="true"><use href="#showcase-icon-media"/></svg><span class="ui-rail-label">Media</span></label></nav><main class="ui-shell-main" tabindex="0" aria-label="Content, scrollable"><section class="ui-shell-section" data-section="overview" aria-labelledby="showcase-h-overview"><h2 id="showcase-h-overview">One shell, any content</h2><p class="ui-muted">Python builds this page from one spec. Pick a section on the rail (wide screens) or the bottom bar (narrow ones).</p><div class="ui-shell-tags"><span class="ui-tag">Python builds it</span><span class="ui-tag">No reload</span><span class="ui-tag">No script to switch</span><span class="ui-tag">Any theme</span></div><div class="ui-shell-cards"><article class="ui-card ui-shell-card"><svg aria-hidden="true"><use href="#showcase-icon-responsive"/></svg><div><h3>Responsive navigation</h3><p>A rail on wide screens and a bottom bar on narrow ones; both choose the same section.</p></div></article><article class="ui-card ui-shell-card"><svg aria-hidden="true"><use href="#showcase-icon-tune"/></svg><div><h3>Data in, page out</h3><p>Labels, icons and sections come from data, so another repository only supplies its own spec.</p></div></article><article class="ui-card ui-shell-card"><svg aria-hidden="true"><use href="#showcase-icon-layers"/></svg><div><h3>Low coupling</h3><p>Plain ui-* classes and tokens only: every theme, including random ones, applies.</p></div></article></div></section><section class="ui-shell-section" data-section="components" aria-labelledby="showcase-h-components"><h2 id="showcase-h-components">Components</h2><p class="ui-muted">The shared controls, as the current theme draws them.</p><div class="ui-shell-controls"><label for="showcase-demo-input">Input</label><input class="ui-input" id="showcase-demo-input" value="shared semantic HTML"> <button class="ui-button" type="button">Button</button><span class="ui-tag">tag</span></div><article class="ui-panel"><h3>Panel</h3><p class="ui-muted">Muted text on a panel, using the current theme.</p></article></section><section class="ui-shell-section" data-section="data" aria-labelledby="showcase-h-data"><h2 id="showcase-h-data">Data</h2><div class="ui-shell-scroll"><table class="ui-shell-table"><thead><tr><th scope="col">Piece</th><th scope="col">Written in</th><th scope="col">Checked by</th></tr></thead><tbody><tr><td>Rules</td><td>Python</td><td>unit tests</td></tr><tr><td>Page script</td><td>JavaScript</td><td>Chromium, against Python</td></tr><tr><td>Styles</td><td>CSS, from Python</td><td>contrast and layout sweeps</td></tr></tbody></table></div></section><section class="ui-shell-section" data-section="media" aria-labelledby="showcase-h-media"><h2 id="showcase-h-media">Media</h2><p class="ui-muted">Images are plain img elements with alt text; data-ui-lightbox opens them larger.</p><div class="ui-shell-tags"><span class="ui-tag">img</span><span class="ui-tag">alt text</span><span class="ui-tag">lightbox</span></div></section></main></div><nav class="ui-bottom-nav" aria-label="Sections (compact)"><label class="ui-bottom-item" for="showcase-sec-overview"><svg aria-hidden="true"><use href="#showcase-icon-overview"/></svg><span class="ui-bottom-label">Overview</span></label><label class="ui-bottom-item" for="showcase-sec-components"><svg aria-hidden="true"><use href="#showcase-icon-components"/></svg><span class="ui-bottom-label">Components</span></label><label class="ui-bottom-item" for="showcase-sec-data"><svg aria-hidden="true"><use href="#showcase-icon-data"/></svg><span class="ui-bottom-label">Data</span></label><label class="ui-bottom-item" for="showcase-sec-media"><svg aria-hidden="true"><use href="#showcase-icon-media"/></svg><span class="ui-bottom-label">Media</span></label></nav></div><script type="module">/** Set text-only content. User-controlled values are never interpreted as HTML. */
export function setText(target,value){const node=typeof target==="string"?document.querySelector(target):target;if(node)node.textContent=String(value)}
/** Serialize a value for human-readable text output. */
export function prettyJson(value){return JSON.stringify(value,null,2)}
/** Copy a value as text; falls back to a hidden textarea where the async clipboard is missing (plain http, old WebViews). */
export async function copyText(value){const text=String(value);try{await navigator.clipboard.writeText(text)}catch(error){const box=document.createElement("textarea");box.value=text;box.setAttribute("readonly","");box.style.cssText="position:fixed;opacity:0";try{document.body.append(box);box.select();if(typeof document.execCommand!=="function"||!document.execCommand("copy"))throw error}finally{box.remove()}}}
/** Switch data-ui-theme on <body> with no reload: controls are <select data-ui-theme-switch> or radios named ui-theme. The choice is remembered (localStorage, best effort). Returns the theme in effect. */
/** Buttons with data-ui-toggle flip aria-pressed on click (memory only: nothing is saved); data-label-on / data-label-off, when present, rename the button. */
export function bindToggles(root=document){return[...root.querySelectorAll("[data-ui-toggle]")].map(b=>{const sync=()=>{const label=b.getAttribute("aria-pressed")==="true"?b.dataset.labelOn:b.dataset.labelOff;if(label){b.setAttribute("aria-label",label);b.title=label}};b.addEventListener("click",()=>{b.setAttribute("aria-pressed",String(b.getAttribute("aria-pressed")!=="true"));sync()});sync();return b})}
export function bindTheme(root=document,{key="web-ui-theme"}={}){const body=document.body,controls=[...root.querySelectorAll("[data-ui-theme-switch],input[name=ui-theme]")];const known=name=>controls.some(c=>c.tagName==="SELECT"?[...c.options].some(o=>o.value===name):c.value===name);const sync=()=>{for(const c of controls){if(c.tagName==="SELECT")c.value=body.dataset.uiTheme;else c.checked=c.value===body.dataset.uiTheme}};let saved=null;try{saved=localStorage.getItem(key)}catch{}if(saved&&known(saved))body.dataset.uiTheme=saved;sync();for(const c of controls)c.addEventListener("change",()=>{if(!known(c.value))return;body.dataset.uiTheme=c.value;sync();try{localStorage.setItem(key,c.value)}catch{}});return body.dataset.uiTheme}
/** Mark on-screen elements with data-lit (IntersectionObserver); CSS decides what lit looks like. Without IntersectionObserver every element counts as lit. Returns a stop function. */
export function observeLit(targets,{threshold=0.4,root=null}={}){const nodes=typeof targets==="string"?[...document.querySelectorAll(targets)]:[...targets];if(typeof IntersectionObserver==="undefined"){for(const n of nodes)n.dataset.lit="";return()=>{}}const io=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting)e.target.dataset.lit="";else delete e.target.dataset.lit}},{threshold,root});for(const n of nodes)io.observe(n);return()=>io.disconnect()}
/** Click-to-enlarge for <a href="full.png"><img alt="..."></a> items inside [data-ui-lightbox]: one <dialog>; Esc, the backdrop and the close button shut it, arrows, buttons and a 48px swipe step through. Returns {open, close, dialog}, or null without items or <dialog>. */
export function bindLightbox(root=document){const items=[...root.querySelectorAll("[data-ui-lightbox] a[href]")];if(!items.length||typeof HTMLDialogElement==="undefined")return null;const dialog=document.createElement("dialog");dialog.className="ui-lightbox";dialog.setAttribute("aria-label","Image viewer");dialog.innerHTML='<img alt=""><p class="ui-muted"></p><div class="ui-lightbox-bar"><button class="ui-button" type="button" data-step="-1" aria-label="Previous">\u2190</button><button class="ui-button" type="button" data-step="1" aria-label="Next">\u2192</button><button class="ui-button" type="button" data-step="0" aria-label="Close">\u00d7</button></div>';const img=dialog.querySelector("img"),note=dialog.querySelector("p");let at=0,x=null;const show=i=>{at=(i+items.length)%items.length;const a=items[at],t=a.querySelector("img");img.src=a.href;img.alt=note.textContent=t?t.alt:""};const open=i=>{show(i);if(!dialog.open)dialog.showModal()};items.forEach((a,i)=>a.addEventListener("click",e=>{e.preventDefault();open(i)}));dialog.addEventListener("click",e=>{const b=e.target.closest("[data-step]");if(b){const s=Number(b.dataset.step);if(s)show(at+s);else dialog.close()}else if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener("keydown",e=>{if(e.key==="ArrowLeft")show(at-1);if(e.key==="ArrowRight")show(at+1)});dialog.addEventListener("pointerdown",e=>{x=e.clientX});dialog.addEventListener("pointerup",e=>{if(x!==null&&Math.abs(e.clientX-x)>=48)show(at+(e.clientX<x?1:-1));x=null});document.body.append(dialog);return{open,close:()=>dialog.close(),dialog}}

