1px solid var(--ui-border);border-radius:var(--ui-radius)}.ui-tempclip-text{flex:1;min-width:0;max-height:3em;overflow:hidden;white-space:pre-wrap;overflow-wrap:anywhere}}
/* css/shell.css */
@layer components{.ui-shell{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;height:100vh;height:100dvh;min-width:0;background:var(--ui-bg);color:var(--ui-fg)}.ui-shell-radio{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}.ui-shell-icons{position:absolute;width:0;height:0;overflow:hidden}.ui-shell svg{width:24px;height:24px;flex:none;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.ui-shell-header{display:flex;align-items:center;gap:8px;min-height:56px;padding:0 8px;background:var(--ui-panel);border-bottom:1px solid var(--ui-border)}.ui-shell-title{flex:1;min-width:0;margin:0 8px;font-size:1.25rem;font-weight:400;line-height:1.25;overflow-wrap:anywhere}.ui-shell-actions{display:flex;align-items:center;gap:8px;flex:none}.ui-shell-actions .ui-input{padding:8px;max-width:128px}.ui-icon-button{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;padding:0;border-radius:50%;flex:none;cursor:pointer}.ui-icon-button[aria-pressed=true] svg{fill:currentColor}.ui-shell-body{display:flex;min-height:0}.ui-rail{display:none;flex-direction:column;gap:8px;width:80px;flex:none;padding:8px;border-right:1px solid var(--ui-border);background:var(--ui-panel);overflow:auto}.ui-rail-item,.ui-bottom-item{display:flex;align-items:center;gap:16px;min-height:48px;padding:0 16px;border-radius:var(--ui-radius);cursor:pointer}.ui-rail-label,.ui-bottom-label{font-size:.75rem}.ui-shell-main{flex:1;min-width:0;min-height:0;overflow-x:hidden;overflow-y:auto;padding:24px;overscroll-behavior:contain}.ui-shell-main h2{margin:0 0 16px;font-size:1.5rem;font-weight:400}.ui-shell-tags{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 24px}.ui-shell-cards{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(256px,1fr))}.ui-shell-card{display:flex;gap:16px;margin:0;min-width:0}.ui-shell-card h3{margin:0 0 8px;font-size:1rem;font-weight:400}.ui-shell-card p{margin:0;overflow-wrap:anywhere}.ui-shell-table{width:100%;border-collapse:collapse}.ui-shell-table th,.ui-shell-table td{padding:8px 16px;border-bottom:1px solid var(--ui-border);text-align:left}.ui-shell-scroll{overflow-x:auto}.ui-shell-controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.ui-bottom-nav{display:flex;border-top:1px solid var(--ui-border);background:var(--ui-panel)}.ui-bottom-item{flex:1;flex-direction:column;justify-content:center;gap:0;min-height:64px;padding:8px 0;text-align:center}@media(min-width:900px){.ui-rail{display:flex}.ui-bottom-nav{display:none}.ui-rail-item{justify-content:center;padding:0}.ui-rail-label{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}}@media(min-width:1200px){.ui-rail{width:256px}.ui-rail-item{justify-content:flex-start;padding:0 16px}.ui-rail-label{position:static;width:auto;height:auto;margin:0;overflow:visible;clip-path:none;white-space:normal}}@media(max-height:480px){.ui-shell{height:auto;min-height:100dvh}.ui-shell-body{min-height:240px}.ui-shell-main{overflow:visible}}@media(prefers-reduced-motion:reduce){.ui-shell-main{scroll-behavior:auto}}}
/* css/stub.css */
@layer components{
.stub-shell{display:grid;gap:1rem}
/* Keep title/description and metadata side-by-side when space permits; wrap rather than compress either region. */
.stub-header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;flex-wrap:wrap}
.stub-toolbar{display:flex;gap:.5rem;flex-wrap:wrap}
.stub-toolbar fieldset{display:flex;gap:.5rem;align-items:end;flex-wrap:wrap;width:100%;border:0;padding:0;margin:0}
.stub-toolbar label{display:block}
.stub-toolbar .ui-input{flex:1 1 16rem}
.stub-status{margin:.75rem 0 0}
.stub-meta{display:flex;gap:.5rem;flex-wrap:wrap;margin:.75rem 0}
/* Primary result pane + secondary evidence/history sidebar. */
.stub-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(16rem,.45fr);gap:1rem}
.stub-result,.stub-evidence,.stub-history{min-width:0}
.stub-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--ui-border)}
.stub-endpoint{overflow-wrap:anywhere}
@media(max-width:720px){.stub-workspace{grid-template-columns:1fr}.stub-header{display:block}}
}
/* css/studio.css */
@layer components{.ui-studio h3{margin:24px 0 8px}.ui-studio label{display:inline-block;margin:8px 8px 4px 0}.ui-studio-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-studio-bar legend{padding:0 0 4px}.ui-studio-bar label{margin:0}.ui-studio-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-studio-row .ui-input{flex:1 1 192px;min-width:0}.ui-studio textarea.ui-input{width:100%;box-sizing:border-box}.ui-beats{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-beat{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border:1px solid var(--ui-border);border-radius:50%}.ui-beat[data-on]{background:var(--ui-accent);color:var(--ui-bg)}.ui-studio-bars{margin:8px 0;padding-left:24px}.ui-studio-bars li[data-error]{color:var(--ui-danger)}.ui-studio-chords{margin:8px 0;overflow-wrap:anywhere}.ui-studio-degrees{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}}
/* css/themes/github-like.css */
/* GitHub-like prioritizes familiar light GitHub visual cues while remaining a generic light theme. */
@layer theme{
body[data-ui-theme="github-like"]{
  --ui-bg:#ffffff;
  --ui-panel:#f6f8fa;
  --ui-fg:#1f2328;
  --ui-muted:#59636e;
  --ui-border:#d0d7de;
  --ui-accent:#0969da;
}
body[data-ui-theme="github-like"] .ui-panel,
body[data-ui-theme="github-like"] .ui-card{
  background:var(--ui-panel);
  border-radius:.375rem;
  box-shadow:none;
}
body[data-ui-theme="github-like"] .ui-button,
body[data-ui-theme="github-like"] .ui-input{
  background:#ffffff;
}
body[data-ui-theme="github-like"] .ui-title{
  border-bottom:1px solid var(--ui-border);
  padding-bottom:.5rem;
}
body[data-ui-theme="github-like"] .ui-tag{
  border-radius:999px;
  color:var(--ui-accent);
}
}
/* css/themes/modern.css */
@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><section class="ui-panel ui-studio" id="studio" data-ui-studio><h2>Composition studio</h2><p class="ui-muted">Theory is computed from music rules, not stored. Python is the reference and this page gives the same answers.</p><h3>Metronome</h3><div class="ui-studio-row"><label for="studio-bpm">Tempo</label><input type="range" id="studio-bpm" min="30" max="300" value="120" data-bpm> <output data-bpm-out>120 BPM</output></div><fieldset class="ui-studio-bar"><legend>Time signature</legend><label><input type="radio" name="studio-sig" value="4/4" checked> 4/4</label><label><input type="radio" name="studio-sig" value="3/4"> 3/4</label><label><input type="radio" name="studio-sig" value="6/8"> 6/8</label></fieldset><div class="ui-beats" data-beats role="img" aria-label="Beat indicator"></div><p class="ui-muted" data-beat-info></p><div class="ui-studio-row"><button class="ui-button" type="button" data-run aria-pressed="false">Start</button><button class="ui-button" type="button" data-tap>Tap tempo</button></div><h3>Chord theory</h3><div class="ui-studio-row"><label for="studio-key">Key</label><select class="ui-input" id="studio-key" data-key><option value="C">C</option><option value="C♯">C♯</option><option value="D♭">D♭</option><option value="D">D</option><option value="D♯">D♯</option><option value="E♭">E♭</option><option value="E">E</option><option value="F">F</option><option value="F♯">F♯</option><option value="G♭">G♭</option><option value="G">G</option><option value="G♯">G♯</option><option value="A♭">A♭</option><option value="A">A</option><option value="A♯">A♯</option><option value="B♭">B♭</option><option value="B">B</option></select><button class="ui-button" type="button" data-semi-down>Semitone down</button><button class="ui-button" type="button" data-semi-up>Semitone up</button></div><fieldset class="ui-studio-bar"><legend>Mode</legend><label><input type="radio" name="studio-mode" value="Major" checked> Major</label><label><input type="radio" name="studio-mode" value="Minor"> Minor</label></fieldset><div class="ui-studio-row"><span>Circle of fifths</span><button class="ui-button" type="button" data-fifth-left></button><button class="ui-button" type="button" data-fifth-right></button></div><div class="ui-studio-degrees" data-degrees></div><div class="ui-studio-row"><label for="studio-prog">Progression (Roman numerals)</label><input class="ui-input" id="studio-prog" data-prog value="I V vi IV" autocomplete="off"></div><p class="ui-studio-chords" data-prog-out></p><div class="ui-studio-row"><label for="studio-degree">Chord builder</label><select class="ui-input" id="studio-degree" data-degree><option value="1">Degree 1</option><option value="2">Degree 2</option><option value="3">Degree 3</option><option value="4">Degree 4</option><option value="5">Degree 5</option><option value="6">Degree 6</option><option value="7">Degree 7</option></select><select class="ui-input" id="studio-mod" aria-label="Quality or extension" data-mod><option value="triad">triad</option><option value="6">6</option><option value="m6">m6</option><option value="7">7</option><option value="maj7">maj7</option><option value="m7">m7</option><option value="m7♭5">m7♭5</option><option value="sus2">sus2</option><option value="sus4">sus4</option><option value="add9">add9</option><option value="add11">add11</option><option value="dim">dim</option><option value="aug">aug</option></select></div><fieldset class="ui-studio-bar"><legend>Inversion</legend><label><input type="radio" name="studio-inv" value="0" checked> Root</label><label><input type="radio" name="studio-inv" value="1"> 1st</label><label><input type="radio" name="studio-inv" value="2"> 2nd</label><label><input type="radio" name="studio-inv" value="3"> 3rd</label></fieldset><p class="ui-studio-chords" data-chord></p><h3>Note sequence</h3><div class="ui-studio-row"><label for="studio-notes">Notes</label><select class="ui-input" id="studio-note-unit" aria-label="Note value" data-note-unit><option value="4">Quarter notes</option><option value="8" selected>Eighth notes</option></select></div><textarea class="ui-input" id="studio-notes" rows="2" data-notes>C3 D3 C3 D3 G3 A3 G3 C4</textarea><ol class="ui-studio-bars" data-bars></ol><h3>Song seed</h3><div class="ui-studio-row"><button class="ui-button" type="button" data-new-seed>New song seed</button></div><p class="ui-studio-chords" data-seed-out>Press the button for a key, tempo, time signature and progression.</p></section></main><script type="module">/* web-ui composition: chord theory, metronome timing, tap tempo, note sequences and a seeded song seed. Python (web_ui.chord_with_inversion, metronome_position, ...) is the reference. */
export const FLAT_KEYS=["C","D♭","D","E♭","E","F","G♭","G","A♭","A","B♭","B"],SHARP_KEYS=["C","C♯","D","D♯","E","F","F♯","G","G♯","A","A♯","B"];
export const SELECTABLE_KEYS=["C","C♯","D♭","D","D♯","E♭","E","F","F♯","G♭","G","G♯","A♭","A","A♯","B♭","B"];
export const CHORD_MODIFIERS=["triad","6","m6","7","maj7","m7","m7♭5","sus2","sus4","add9","add11","dim","aug"];
const MAJOR=[0,2,4,5,7,9,11],MINOR=[0,2,3,5,7,8,10],MAJOR_Q=["","m","m","","","m","dim"],MINOR_Q=["m","dim","","m","m","","" ],LETTERS="CDEFGAB",NAT={C:0,D:2,E:4,F:5,G:7,A:9,B:11};
const INTERVALS={triad:[0,4,7],"6":[0,4,7,9],m6:[0,3,7,9],"7":[0,4,7,10],maj7:[0,4,7,11],m7:[0,3,7,10],"m7♭5":[0,3,6,10],sus2:[0,2,7],sus4:[0,5,7],add9:[0,4,7,14],add11:[0,4,7,17],dim:[0,3,6],dim7:[0,3,6,9],aug:[0,4,8]};
const ROMAN={I:1,II:2,III:3,IV:4,V:5,VI:6,VII:7},mod=(n,m)=>((n%m)+m)%m,trim=s=>s.replace(/^[ \t\r\n\f\v]+|[ \t\r\n\f\v]+$/g,"");
export function pitchClass(note){const m=typeof note==="string"?/^([A-G])([♯♭]*)$/.exec(note):null;if(!m)throw new Error("unsupported note: "+note);
 const sharps=(m[2].match(/♯/g)||[]).length,flats=(m[2].match(/♭/g)||[]).length;return mod(NAT[m[1]]+sharps-flats,12)}
export const prefersSharps=key=>key.includes("♯")||["D","E","G","A","B"].includes(key);
export const noteForPitchClass=(v,sharps)=>(sharps?SHARP_KEYS:FLAT_KEYS)[mod(v,12)];
export const transposeKey=(key,n)=>noteForPitchClass(pitchClass(key)+n,prefersSharps(key));
export const fifthNeighbor=(key,clockwise)=>transposeKey(key,clockwise?7:-7);
function spell(letter,v){let d=mod(v,12)-NAT[letter];d=d>6?d-12:d<-6?d+12:d;if(![-2,-1,0,1,2].includes(d))throw new Error("cannot spell pitch");return letter+({"-2":"♭♭","-1":"♭","0":"","1":"♯","2":"♯♯"})[d]}
export function scale(key,minor){const root=pitchClass(key),first=LETTERS.indexOf(key.slice(0,1));if(first<0)throw new Error("unsupported root letter");const steps=minor?MINOR:MAJOR;return steps.map((st,d)=>spell(LETTERS[(first+d)%7],root+st))}
export function diatonicChord(key,degree,minor){if(!Number.isInteger(degree)||degree<1||degree>7)throw new Error("degree must be 1 through 7");return scale(key,minor)[degree-1]+(minor?MINOR_Q:MAJOR_Q)[degree-1]}
export function romanDegree(token){const m=/^[ivIV]+/.exec(trim(token));return m&&ROMAN[m[0].toUpperCase()]||null}
export function convertRomanToken(key,token,minor){const t=trim(token),m=/^([ivIV]+)([\s\S]*)$/.exec(t),degree=m?romanDegree(t):null;if(!m||degree===null)return token;
 const root=scale(key,minor)[degree-1],base=diatonicChord(key,degree,minor),suffix=trim(m[2]);
 if(!suffix)return base;if(suffix==="6"||suffix==="7")return base+suffix;if(suffix==="m6")return root+"m6";if(["maj7","M7","△7"].includes(suffix))return root+"maj7";if(suffix==="m7")return root+"m7";
 if(["m7♭5","ø7"].includes(suffix))return root+"m7♭5";if(["sus2","sus4","add9","add11"].includes(suffix))return root+suffix;if(["dim","°"].includes(suffix))return root+"dim";if(["aug","+"].includes(suffix))return root+"aug";return base}
export function convertProgression(key,progression,minor){for(const d of "–—-|")progression=progression.split(d).join(" ");return progression.split(/[ \t\r\n\f\v,]+/).filter(Boolean).map(t=>convertRomanToken(key,t,minor))}
export function applyModifier(root,modifier){if(!CHORD_MODIFIERS.includes(modifier))throw new Error("unsupported chord modifier");return modifier==="triad"?root:root+modifier}
export function chordTones(root,modifier){if(!Object.hasOwn(INTERVALS,modifier))throw new Error("unsupported chord modifier");const start=pitchClass(root),sharps=prefersSharps(root);return INTERVALS[modifier].map(i=>noteForPitchClass(start+i,sharps))}
export function normalizedInversion(modifier,inversion){if(!Number.isInteger(inversion)||inversion<0||inversion>3)throw new Error("inversion must be 0 through 3");const n=INTERVALS[modifier].length;return inversion<n?inversion:n===3&&inversion===3?1:inversion%n}
export function chordWithInversion(root,modifier,inversion){const chord=applyModifier(root,modifier),n=normalizedInversion(modifier,inversion);return n===0?chord:chord+"/"+chordTones(root,modifier)[n]}
const half=v=>Math.floor(v+0.5);
export const beatMicros=bpm=>half(60000000/Math.min(Math.max(bpm,30),300));
export function subdivisionMicros(bpm,per){if(!(per>0))throw new Error("subdivisions per beat must be positive");return half(beatMicros(bpm)/per)}
export function barMicros(bpm,beats){if(!(beats>0))throw new Error("beats per bar must be positive");return beatMicros(bpm)*beats}
export function metronomePosition(elapsed,bpm,beats,per){if(!(beats>0&&per>0))throw new Error("beats per bar and subdivisions must be positive");const unit=subdivisionMicros(bpm,per),e=Math.max(elapsed,0),steps=Math.floor(e/unit);return[Math.floor(steps/per)%beats,steps%per,(e%unit)/unit]}
export function durationLabel(micros){if(micros>=1000000){const h=half(micros/10000);return Math.floor(h/100)+"."+String(h%100).padStart(2,"0")+" s"}return half(micros/1000)+" ms"}
export function tapTempo(taps,tap,resetGap=2000000,maxIntervals=5){const kept=taps.length&&tap-taps[taps.length-1]>resetGap?[]:[...taps];kept.push(tap);if(kept.length>maxIntervals+1)kept.shift();if(kept.length<2)return[kept,null];
 const avg=(kept[kept.length-1]-kept[0])/(kept.length-1);if(avg<=0)return[kept,null];return[kept,Math.min(Math.max(half(60000000/avg),30),300)]}
export function parseNotes(text){const out=[];for(const token of text.split(/[ \t\r\n\f\v,]+/)){if(!token)continue;const m=/^([A-Ga-g])([#b♯♭]?)(-?[0-9])$/.exec(token);if(!m)throw new Error("invalid note: "+token);out.push(m[1].toUpperCase()+({"#":"♯",b:"♭"}[m[2]]??m[2])+m[3])}return out}
export function notesPerBar(beats,unit,noteUnit){if(noteUnit!==4&&noteUnit!==8)throw new Error("only quarter and eighth notes are supported");const v=beats*noteUnit/unit;if(!Number.isInteger(v)||v<=0)throw new Error("the selected note value does not divide this bar evenly");return v}
export function noteBars(notes,beats,unit,noteUnit){const size=notesPerBar(beats,unit,noteUnit),out=[];for(let i=0;i<notes.length;i+=size)out.push(notes.slice(i,i+size));return out}
export function mulberry32(seed){let a=seed>>>0;return()=>{a=(a+0x<addr>)>>>0;let t=Math.imul(a^a>>>15,a|1);t=((t+Math.imul(t^t>>>7,t|61))^t)>>>0;return((t^t>>>14)>>>0)/4294967296}}
export const SEED_KEYS=["B♭","B","C","D♭","D","E♭","E","F","G♭","G","A♭","A"],SEED_MODES=["Major","Minor"],SEED_TIMES=["4/4","3/4","6/8"];
export const SEED_PROGRESSIONS={Major:["I – V – vi – IV","I – vi – IV – V","ii – V – I – vi","I – IV – V – IV"],Minor:["i – VI – III – VII","i – iv – VII – III","i – VII – VI – VII","i – iv – v – i"]};
export function songSeed(seed,avoid=null){const rng=mulberry32(seed),pick=o=>o[Math.floor(rng()*o.length)];let result;
 for(let i=0;i<8;i++){const mode=pick(SEED_MODES);result={tonic:pick(SEED_KEYS),mode,bpm:80+Math.floor(rng()*81),time:pick(SEED_TIMES),progression:pick(SEED_PROGRESSIONS[mode])};
  if(avoid===null||JSON.stringify(result)!==JSON.stringify(avoid))break}return result}
export const songSeedText=s=>"Key: "+s.tonic+" "+s.mode+" · BPM: "+s.bpm+" · Time: "+s.time+" · Progression: "+s.progression;
export function bindStudio(root=document){return[...root.querySelectorAll("[data-ui-studio]")].map(box=>{
 const $=s=>box.querySelector(s),$$=s=>[...box.querySelectorAll(s)],checked=n=>box.querySelector('input[name="'+n+'"]:checked').value;
 const el={bpm:$("[data-bpm]"),bpmOut:$("[data-bpm-out]"),beats:$("[data-beats]"),info:$("[data-beat-info]"),run:$("[data-run]"),tap:$("[data-tap]"),key:$("[data-key]"),prog:$("[data-prog]"),progOut:$("[data-prog-out]"),
  degrees:$("[data-degrees]"),fifths:$("[data-fifths]"),degree:$("[data-degree]"),mod:$("[data-mod]"),chord:$("[data-chord]"),notes:$("[data-notes]"),noteUnit:$("[data-note-unit]"),bars:$("[data-bars]"),seed:$("[data-seed-out]")};
 const sig=()=>checked("studio-sig").split("/").map(Number),minor=()=>checked("studio-mode")==="Minor";let running=false,t0=0,taps=[],raf=0;
 const text=(n,t)=>{n.textContent=t};
 const drawBeats=()=>{const[b]=sig();el.beats.replaceChildren(...Array.from({length:b},(_,i)=>{const d=document.createElement("span");d.className="ui-beat";d.dataset.i=i;d.textContent=i+1;return d}))};
 const tick=()=>{const[b,u]=sig(),bpm=Number(el.bpm.value),[beat,sub,phase]=metronomePosition((performance.now()-t0)*1000,bpm,b,2);box.dataset.beat=beat;box.dataset.sub=sub;
  for(const d of el.beats.children)d.toggleAttribute("data-on",Number(d.dataset.i)===beat);
  text(el.info,"Beat "+(beat+1)+"/"+b+" · "+durationLabel(beatMicros(bpm))+" per beat · bar "+durationLabel(barMicros(bpm,b)));if(running)raf=requestAnimationFrame(tick)};
 const idle=()=>{const[b]=sig(),bpm=Number(el.bpm.value);text(el.bpmOut,bpm+" BPM");text(el.info,b+"/"+sig()[1]+" · beat "+durationLabel(beatMicros(bpm))+" · bar "+durationLabel(barMicros(bpm,b)))};
 const restart=()=>{if(running)t0=performance.now();idle()};
 el.bpm.addEventListener("input",restart);for(const r of $$('input[name="studio-sig"]'))r.addEventListener("change",()=>{drawBeats();restart();notes()});
