.stub-toolbar label{display:block}
.stub-toolbar .ui-input{flex:1 1 16rem}
.stub-status{margin:.75rem 0 0}
.stub-meta{display:flex;gap:.5rem;flex-wrap:wrap;margin:.75rem 0}
/* Primary result pane + secondary evidence/history sidebar. */
.stub-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(16rem,.45fr);gap:1rem}
.stub-result,.stub-evidence,.stub-history{min-width:0}
.stub-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--ui-border)}
.stub-endpoint{overflow-wrap:anywhere}
@media(max-width:720px){.stub-workspace{grid-template-columns:1fr}.stub-header{display:block}}
}
/* css/studio.css */
@layer components{.ui-studio h3{margin:24px 0 8px}.ui-studio label{display:inline-block;margin:8px 8px 4px 0}.ui-studio-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-studio-bar legend{padding:0 0 4px}.ui-studio-bar label{margin:0}.ui-studio-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-studio-row .ui-input{flex:1 1 192px;min-width:0}.ui-studio textarea.ui-input{width:100%;box-sizing:border-box}.ui-beats{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-beat{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border:1px solid var(--ui-border);border-radius:50%}.ui-beat[data-on]{background:var(--ui-accent);color:var(--ui-bg)}.ui-studio-bars{margin:8px 0;padding-left:24px}.ui-studio-bars li[data-error]{color:var(--ui-danger)}.ui-studio-chords{margin:8px 0;overflow-wrap:anywhere}.ui-studio-degrees{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}}
/* css/themes/github-like.css */
/* GitHub-like prioritizes familiar light GitHub visual cues while remaining a generic light theme. */
@layer theme{
body[data-ui-theme="github-like"]{
  --ui-bg:#ffffff;
  --ui-panel:#f6f8fa;
  --ui-fg:#1f2328;
  --ui-muted:#59636e;
  --ui-border:#d0d7de;
  --ui-accent:#0969da;
}
body[data-ui-theme="github-like"] .ui-panel,
body[data-ui-theme="github-like"] .ui-card{
  background:var(--ui-panel);
  border-radius:.375rem;
  box-shadow:none;
}
body[data-ui-theme="github-like"] .ui-button,
body[data-ui-theme="github-like"] .ui-input{
  background:#ffffff;
}
body[data-ui-theme="github-like"] .ui-title{
  border-bottom:1px solid var(--ui-border);
  padding-bottom:.5rem;
}
body[data-ui-theme="github-like"] .ui-tag{
  border-radius:999px;
  color:var(--ui-accent);
}
}
/* css/themes/modern.css */
@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><section class="ui-panel ui-door" id="door" data-ui-door data-door-draws="0" data-door="{&quot;pages&quot;:[{&quot;emoji&quot;:&quot;🏠&quot;,&quot;label&quot;:&quot;Home&quot;,&quot;href&quot;:&quot;../index.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🧭&quot;,&quot;label&quot;:&quot;Examples&quot;,&quot;href&quot;:&quot;./index.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;📋&quot;,&quot;label&quot;:&quot;Clipboard shelf&quot;,&quot;href&quot;:&quot;./clipboard-shelf.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🎨&quot;,&quot;label&quot;:&quot;App shell showcase&quot;,&quot;href&quot;:&quot;./showcase.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🕸️&quot;,&quot;label&quot;:&quot;MCP stub&quot;,&quot;href&quot;:&quot;./mcp-stub.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🌐&quot;,&quot;label&quot;:&quot;API stub&quot;,&quot;href&quot;:&quot;./api-stub.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🐙&quot;,&quot;label&quot;:&quot;GitHub-like theme&quot;,&quot;href&quot;:&quot;./github-like.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🚪&quot;,&quot;label&quot;:&quot;Door-to-Door&quot;,&quot;href&quot;:&quot;./door.html&quot;,&quot;group&quot;:&quot;stable&quot;},{&quot;emoji&quot;:&quot;🗺️&quot;,&quot;label&quot;:&quot;World&quot;,&quot;href&quot;:&quot;../index.html#world&quot;,&quot;group&quot;:&quot;discover&quot;},{&quot;emoji&quot;:&quot;🔗&quot;,&quot;label&quot;:&quot;Request draft&quot;,&quot;href&quot;:&quot;../index.html#curl&quot;,&quot;group&quot;:&quot;discover&quot;},{&quot;emoji&quot;:&quot;🌈&quot;,&quot;label&quot;:&quot;Random themes&quot;,&quot;href&quot;:&quot;../index.html#wall&quot;,&quot;group&quot;:&quot;discover&quot;},{&quot;emoji&quot;:&quot;🎛️&quot;,&quot;label&quot;:&quot;Try it&quot;,&quot;href&quot;:&quot;../index.html#try&quot;,&quot;group&quot;:&quot;discover&quot;},{&quot;emoji&quot;:&quot;🧪&quot;,&quot;label&quot;:&quot;MCP on the front page&quot;,&quot;href&quot;:&quot;../index.html#mcp&quot;,&quot;group&quot;:&quot;discover&quot;},{&quot;emoji&quot;:&quot;📡&quot;,&quot;label&quot;:&quot;API on the front page&quot;,&quot;href&quot;:&quot;../index.html#api&quot;,&quot;group&quot;:&quot;discover&quot;}],&quot;k&quot;:3,&quot;seed&quot;:20261103,&quot;current&quot;:&quot;./door.html&quot;}"><h2>Door-to-Door</h2><p class="ui-muted">Jump to another tool without going Home first. Some entries are drawn at random; the same seed draws the same ones in Python and here.</p><label for="door-select">Door-to-Door tools</label><div class="ui-door-row"><select class="ui-input" id="door-select" data-door-select><option value="../index.html">🏠 Home</option><option value="../index.html#curl">🔗 Request draft</option><option value="../index.html#try">🎛️ Try it</option><option value="../index.html#api">📡 API on the front page</option><option value="./index.html">🧭 Examples</option><option value="./clipboard-shelf.html">📋 Clipboard shelf</option><option value="./showcase.html">🎨 App shell showcase</option><option value="./mcp-stub.html">🕸️ MCP stub</option><option value="./api-stub.html">🌐 API stub</option><option value="./github-like.html">🐙 GitHub-like theme</option><option value="./door.html" selected disabled>🚪 Door-to-Door (current)</option></select> <button class="ui-button" type="button" data-door-draw>Draw again</button></div><p class="ui-muted" role="status" aria-live="polite" data-door-status>Pick a destination.</p><h3>Transitions by emoji</h3><p class="ui-muted"><code>A → B</code> goes, <code>A ↔ B</code> goes and comes back. Spaces and variation selectors are ignored.</p><label for="door-notation">Notation</label><input class="ui-input" id="door-notation" data-door-notation value="🏠 ↔ 🧭" autocomplete="off"><ol class="ui-door-path" data-door-path></ol><p class="ui-muted" role="status" data-door-note></p></section></main><script type="module">/* web-ui door: a Door-to-Door pull-down, emoji transitions ("A → B", "A ↔ B") and a seeded draw. Python (web_ui.door_options, emoji_path, door_draw) is the reference. */
const DROP="\\ufe0e\\ufe0f \\t\\n\\v\\f\\r\\x1c-\\x1f\\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
export const emojiKey=e=>e.replace(new RegExp("["+DROP+"]","g"),"");
export function emojiPath(notation,pages){
 const by=new Map(pages.map(p=>[emojiKey(p.emoji),p.href])),parts=emojiKey(notation).split(/([→↔])/),path=[parts[0]];
 for(let i=1;i+1<parts.length;i+=2){const there=parts[i+1];if(parts[i]==="→")path.push(there);else path.push(there,path[path.length-1])}
 return path.map(k=>{if(!by.has(k))throw new Error("unknown page emoji: "+JSON.stringify(k));return by.get(k)})}
export function mulberry32(seed){let a=seed>>>0;return()=>{a=(a+0x<addr>)>>>0;let t=Math.imul(a^a>>>15,a|1);t=((t+Math.imul(t^t>>>7,t|61))^t)>>>0;return((t^t>>>14)>>>0)/4294967296}}
export function doorDraw(seed,count,k){if(!(k>=0&&k<=count))throw new Error("k must be from 0 to count");const rng=mulberry32(seed),order=Array.from({length:count},(_,i)=>i);
 for(let i=0;i<k;i++){const j=i+Math.floor(rng()*(count-i));[order[i],order[j]]=[order[j],order[i]]}return order.slice(0,k)}
export function doorOptions(door,seed=door.seed){const stable=door.pages.filter(p=>p.group==="stable"),found=door.pages.filter(p=>p.group==="discover"),drawn=doorDraw(seed,found.length,door.k).map(i=>found[i]);
 return[stable[0],...drawn,...stable.slice(1)].map(p=>({...p,current:p.href===door.current,drawn:drawn.includes(p)}))}
const safe=href=>{try{const u=new URL(href,location.href);return u.protocol==="http:"||u.protocol==="https:"}catch(e){return false}};
export function bindDoor(root=document){return[...root.querySelectorAll("[data-ui-door]")].map(box=>{
 const door=JSON.parse(box.dataset.door),$=s=>box.querySelector(s),select=$("[data-door-select]"),status=$("[data-door-status]");let seed=door.seed;
 const fill=()=>{select.replaceChildren(...doorOptions(door,seed).map(o=>{const op=document.createElement("option");op.value=o.href;op.textContent=o.emoji+" "+o.label+(o.current?" (current)":"");if(o.current){op.selected=true;op.disabled=true}return op}))};
 select.addEventListener("change",()=>{const href=select.value,page=door.pages.find(p=>p.href===href);if(!page||href===door.current)return;
  const stay=!box.dispatchEvent(new CustomEvent("ui-door-leave",{cancelable:true,bubbles:true,detail:{href,emoji:page.emoji,label:page.label}}));
  if(stay){fill();status.textContent="Staying here.";return}
  if(!safe(href)){status.textContent="That destination is not allowed.";fill();return}
  status.textContent="Opening "+page.label+"…";box.dispatchEvent(new CustomEvent("ui-door-go",{bubbles:true,detail:{href}}));if(!box.hasAttribute("data-door-dry"))location.assign(href)});
 $("[data-door-draw]").addEventListener("click",()=>{seed=Math.floor(Math.random()*4294967296);fill();box.setAttribute("data-door-draws",String(Number(box.getAttribute("data-door-draws")||0)+1));status.textContent="Drew new entries (seed "+seed+")."});
 const input=$("[data-door-notation]"),path=$("[data-door-path]"),note=$("[data-door-note]");
 const show=()=>{try{const hrefs=emojiPath(input.value,door.pages);path.replaceChildren(...hrefs.map(h=>{const li=document.createElement("li"),a=document.createElement("a");a.textContent=h;if(safe(h))a.href=h;li.append(a);return li}));note.textContent=hrefs.length+" page(s)."}catch(e){path.replaceChildren();note.textContent=e.message}};
 input.addEventListener("input",show);fill();show();box.dataset.door_ready="";return box})}
globalThis.webUiDoor={emojiKey,emojiPath,mulberry32,doorDraw,doorOptions,bindDoor};
if(typeof document!=="undefined")bindDoor();
</script></body></html>
