-size:1rem;font-weight:400}.ui-shell-card p{margin:0;overflow-wrap:anywhere}.ui-shell-table{width:100%;border-collapse:collapse}.ui-shell-table th,.ui-shell-table td{padding:8px 16px;border-bottom:1px solid var(--ui-border);text-align:left}.ui-shell-scroll{overflow-x:auto}.ui-shell-controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.ui-bottom-nav{display:flex;border-top:1px solid var(--ui-border);background:var(--ui-panel)}.ui-bottom-item{flex:1;flex-direction:column;justify-content:center;gap:0;min-height:64px;padding:8px 0;text-align:center}@media(min-width:900px){.ui-rail{display:flex}.ui-bottom-nav{display:none}.ui-rail-item{justify-content:center;padding:0}.ui-rail-label{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}}@media(min-width:1200px){.ui-rail{width:256px}.ui-rail-item{justify-content:flex-start;padding:0 16px}.ui-rail-label{position:static;width:auto;height:auto;margin:0;overflow:visible;clip-path:none;white-space:normal}}@media(max-height:480px){.ui-shell{height:auto;min-height:100dvh}.ui-shell-body{min-height:240px}.ui-shell-main{overflow:visible}}@media(prefers-reduced-motion:reduce){.ui-shell-main{scroll-behavior:auto}}}
/* css/stub.css */
@layer components{
.stub-shell{display:grid;gap:1rem}
/* Keep title/description and metadata side-by-side when space permits; wrap rather than compress either region. */
.stub-header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;flex-wrap:wrap}
.stub-toolbar{display:flex;gap:.5rem;flex-wrap:wrap}
.stub-toolbar fieldset{display:flex;gap:.5rem;align-items:end;flex-wrap:wrap;width:100%;border:0;padding:0;margin:0}
.stub-toolbar label{display:block}
.stub-toolbar .ui-input{flex:1 1 16rem}
.stub-status{margin:.75rem 0 0}
.stub-meta{display:flex;gap:.5rem;flex-wrap:wrap;margin:.75rem 0}
/* Primary result pane + secondary evidence/history sidebar. */
.stub-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(16rem,.45fr);gap:1rem}
.stub-result,.stub-evidence,.stub-history{min-width:0}
.stub-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem;padding-top:.75rem;border-top:1px solid var(--ui-border)}
.stub-endpoint{overflow-wrap:anywhere}
@media(max-width:720px){.stub-workspace{grid-template-columns:1fr}.stub-header{display:block}}
}
/* css/studio.css */
@layer components{.ui-studio h3{margin:24px 0 8px}.ui-studio label{display:inline-block;margin:8px 8px 4px 0}.ui-studio-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-studio-bar legend{padding:0 0 4px}.ui-studio-bar label{margin:0}.ui-studio-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.ui-studio-row .ui-input{flex:1 1 192px;min-width:0}.ui-studio textarea.ui-input{width:100%;box-sizing:border-box}.ui-beats{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-beat{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border:1px solid var(--ui-border);border-radius:50%}.ui-beat[data-on]{background:var(--ui-accent);color:var(--ui-bg)}.ui-studio-bars{margin:8px 0;padding-left:24px}.ui-studio-bars li[data-error]{color:var(--ui-danger)}.ui-studio-chords{margin:8px 0;overflow-wrap:anywhere}.ui-studio-degrees{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}}
/* css/themes/github-like.css */
/* GitHub-like prioritizes familiar light GitHub visual cues while remaining a generic light theme. */
@layer theme{
body[data-ui-theme="github-like"]{
  --ui-bg:#ffffff;
  --ui-panel:#f6f8fa;
  --ui-fg:#1f2328;
  --ui-muted:#59636e;
  --ui-border:#d0d7de;
  --ui-accent:#0969da;
}
body[data-ui-theme="github-like"] .ui-panel,
body[data-ui-theme="github-like"] .ui-card{
  background:var(--ui-panel);
  border-radius:.375rem;
  box-shadow:none;
}
body[data-ui-theme="github-like"] .ui-button,
body[data-ui-theme="github-like"] .ui-input{
  background:#ffffff;
}
body[data-ui-theme="github-like"] .ui-title{
  border-bottom:1px solid var(--ui-border);
  padding-bottom:.5rem;
}
body[data-ui-theme="github-like"] .ui-tag{
  border-radius:999px;
  color:var(--ui-accent);
}
}
/* css/themes/modern.css */
@layer theme{body[data-ui-theme="modern"]{color-scheme:dark}body[data-ui-theme="modern"] .ui-title::before,body[data-ui-theme="modern"] .ui-card>h2::before{content:"> ";color:var(--ui-accent)}body[data-ui-theme="modern"] .ui-panel,body[data-ui-theme="modern"] .ui-card{background:var(--ui-panel);box-shadow:4px 4px 0 rgba(88,166,255,.16)}body[data-ui-theme="modern"] .ui-tag::before{content:"#";color:var(--ui-accent)}}
</style></head><body data-ui-theme="modern"><main class="ui-page"><section class="ui-panel ui-play" id="playground" data-ui-play data-play="{&quot;ironies&quot;:[{&quot;text&quot;:&quot;Humans automate everything, then schedule meetings to discuss the automation.&quot;,&quot;tone&quot;:&quot;Tech&quot;},{&quot;text&quot;:&quot;The strongest password is usually defeated by the person holding it.&quot;,&quot;tone&quot;:&quot;Tech&quot;},{&quot;text&quot;:&quot;We built instant messaging so everyone could wait longer for a reply.&quot;,&quot;tone&quot;:&quot;Tech&quot;},{&quot;text&quot;:&quot;Software saves time until the update starts.&quot;,&quot;tone&quot;:&quot;Tech&quot;},{&quot;text&quot;:&quot;The cloud is just someone else’s computer with better branding.&quot;,&quot;tone&quot;:&quot;Tech&quot;},{&quot;text&quot;:&quot;Everyone values honesty right up until the status report arrives.&quot;,&quot;tone&quot;:&quot;Work&quot;},{&quot;text&quot;:&quot;The shortest meeting is the one that was replaced by an email.&quot;,&quot;tone&quot;:&quot;Work&quot;},{&quot;text&quot;:&quot;A deadline becomes realistic immediately after it is missed.&quot;,&quot;tone&quot;:&quot;Work&quot;},{&quot;text&quot;:&quot;We optimize productivity by adding another productivity tool.&quot;,&quot;tone&quot;:&quot;Work&quot;},{&quot;text&quot;:&quot;The busiest calendar often has the least room for actual work.&quot;,&quot;tone&quot;:&quot;Work&quot;},{&quot;text&quot;:&quot;People buy smart devices so they can spend more time configuring them.&quot;,&quot;tone&quot;:&quot;Daily&quot;},{&quot;text&quot;:&quot;Convenience is carrying five chargers for three devices.&quot;,&quot;tone&quot;:&quot;Daily&quot;},{&quot;text&quot;:&quot;The quickest queue is always the one you did not choose.&quot;,&quot;tone&quot;:&quot;Daily&quot;},{&quot;text&quot;:&quot;A silent notification is still checked immediately.&quot;,&quot;tone&quot;:&quot;Daily&quot;},{&quot;text&quot;:&quot;We save things for later until later needs its own storage plan.&quot;,&quot;tone&quot;:&quot;Daily&quot;},{&quot;text&quot;:&quot;Humans invented maps and still ask which way the station is.&quot;,&quot;tone&quot;:&quot;Human&quot;},{&quot;text&quot;:&quot;Everyone wants a simple answer to a complicated question.&quot;,&quot;tone&quot;:&quot;Human&quot;},{&quot;text&quot;:&quot;Experience is knowing exactly which mistake you are repeating.&quot;,&quot;tone&quot;:&quot;Human&quot;},{&quot;text&quot;:&quot;The more choices we have, the longer we spend choosing nothing.&quot;,&quot;tone&quot;:&quot;Human&quot;},{&quot;text&quot;:&quot;We dislike uncertainty, so we make confident predictions about it.&quot;,&quot;tone&quot;:&quot;Human&quot;}],&quot;status&quot;:{&quot;max&quot;:&quot;Maximum reached 🚀&quot;,&quot;min&quot;:&quot;Minimum reached 🧊&quot;,&quot;high&quot;:&quot;High score territory 🔥&quot;,&quot;low&quot;:&quot;Going underground 🕳️&quot;,&quot;too_much&quot;:&quot;Too much 😈&quot;,&quot;reverse&quot;:&quot;Reverse mode 👻&quot;,&quot;neutral&quot;:&quot;Keep experimenting 👾&quot;}}"><h2>Counter Playground</h2><p class="ui-muted">Count -100 to 100; step 1, 5 or 10; eight recent values; damage or heal. Hold a button to keep stepping. Everything stays in this page.</p><div data-counter><p>Current value</p><p class="ui-counter-value" data-counter-value aria-live="polite">0</p><p class="ui-counter-orbs" data-counter-orbs aria-hidden="true"></p><p class="ui-counter-label" data-counter-label>Orbs ready…</p><p data-counter-status class="ui-muted">Keep experimenting 👾</p><fieldset class="ui-counter-bar"><legend>Step</legend><label><input type="radio" name="counter-step" value="1" checked> Step 1</label><label><input type="radio" name="counter-step" value="5"> Step 5</label><label><input type="radio" name="counter-step" value="10"> Step 10</label></fieldset><div class="ui-counter-actions"><button class="ui-button" type="button" data-counter-decrement>Decrease</button> <button class="ui-button" type="button" data-counter-increment>Increase</button> <button class="ui-button" type="button" data-counter-reset>Reset</button> <button class="ui-button" type="button" data-counter-undo>Undo</button></div><h3>Recent values</h3><p class="ui-muted">Tap a value to restore it.</p><ul class="ui-counter-history" data-counter-history></ul></div><h2 id="irony-title">Irony generator</h2><p class="ui-muted">Drag the card by its handle and let it leave the box to get another message. If only part of the card is out, the handle is brought back inside. The text can be selected and copied.</p><div class="ui-irony-arena" data-irony-arena data-irony-index="0"><div class="ui-irony-card" data-irony-card><button class="ui-irony-handle" type="button" data-irony-handle aria-label="Drag to move message" title="Drag to move message">⠿</button><p class="ui-irony-text" data-irony-text></p><p class="ui-irony-tone ui-muted" data-irony-tone></p></div></div><p><button class="ui-button" type="button" data-irony-next>New irony</button></p></section></main><script type="module">/* web-ui playground: the Counter Playground, the hold-to-repeat button and the Irony generator in the page. Python (web_ui.counter_apply, hold_repeat_count, irony_drop, ...) is the reference; this must agree. */
export function mulberry32(seed){let a=seed>>>0;return()=>{a=(a+0x<addr>)>>>0;let t=Math.imul(a^a>>>15,a|1);t=((t+Math.imul(t^t>>>7,t|61))^t)>>>0;return((t^t>>>14)>>>0)/4294967296}}
export const COUNTER_MIN=-100,COUNTER_MAX=100,COUNTER_STEPS=[1,5,10],COUNTER_HISTORY=8,HOLD_DELAY=350,HOLD_INTERVAL=70,IRONY_PADDING=8;
const ATTACK=["🔥","💧","🌳","💡","🔮"],HEAL=["❤️","💚","✨"],MAX_ORBS=6,ACTIONS=["step","increment","decrement","change","restore","undo","reset"];
const int=(v,n)=>{if(!Number.isInteger(v))throw new Error(n+" must be an integer");return v};
export function counterEffect(counter){int(counter,"counter");if(counter===0)return{counter:0,amount:0,heal:false,idle:true,orbs:[]};
 const heal=counter<0,amount=Math.abs(counter),palette=heal?HEAL:ATTACK;
 return{counter,amount,heal,idle:false,orbs:Array.from({length:Math.min(Math.max(amount,1),MAX_ORBS)},(_,i)=>palette[i%palette.length])}}
export function counterLabel(counter){const e=counterEffect(counter);return e.idle?"Orbs ready…":e.heal?"💚 Heal "+e.amount:"💥 Damage "+e.amount}
export function counterStatusKey(counter){int(counter,"counter");if(counter===COUNTER_MAX)return"max";if(counter===COUNTER_MIN)return"min";
 return counter>=50?"high":counter<=-50?"low":counter>=10?"too_much":counter<=-10?"reverse":"neutral"}
export const counterState=()=>({counter:0,step:1,burst:0,history:[0]});
export function counterApply(state,action,value){
 if(!ACTIONS.includes(action))throw new Error("unknown action: "+action);
 const counter=int(state.counter,"counter"),step=int(state.step,"step"),burst=int(state.burst,"burst"),history=[...state.history];
 if(!history.length||history.some(h=>!Number.isInteger(h))||history[0]!==counter)throw new Error("history must start with the current value");
 const make=(o={})=>({counter,step,burst,history,...o});
 if(action==="step")return Number.isInteger(value)&&COUNTER_STEPS.includes(value)&&value!==step?make({step:value}):make();
 if(action==="undo")return history.length>1?make({counter:history[1],burst:burst+1,history:history.slice(1)}):make();
 let target;
 if(action==="reset")target=0;else if(action==="increment"||action==="decrement")target=counter+(action==="increment"?step:-step);
 else if(action==="change")target=counter+int(value,"delta");else target=int(value,"value");
 target=Math.min(Math.max(target,COUNTER_MIN),COUNTER_MAX);
 return target===counter?make():make({counter:target,burst:burst+1,history:[target,...history].slice(0,COUNTER_HISTORY)})}
export const holdRepeatCount=(heldMs,buttons=1)=>buttons!==1||heldMs<HOLD_DELAY?0:1+Math.floor((heldMs-HOLD_DELAY)/HOLD_INTERVAL);
export const holdSwallowsClick=(heldMs,buttons=1)=>holdRepeatCount(heldMs,buttons)>0;
export function ironyFirst(count,unit){if(count<1||!(unit>=0&&unit<1))throw new Error("count must be at least 1 and unit in [0, 1)");return Math.floor(unit*count)}
export function ironyNext(count,current,unit){if(!(unit>=0&&unit<1))throw new Error("unit must be in [0, 1)");if(count<2)return null;
 const pick=Math.floor(unit*(count-1));return current!==null&&current!==undefined&&current>=0&&current<=pick?pick+1:pick}
export function ironySequence(seed,steps,count){const rng=mulberry32(seed),out=[ironyFirst(count,rng())];for(let i=0;i<steps;i++)out.push(ironyNext(count,out[out.length-1],rng()));return out}
const rect=r=>{if(!Array.isArray(r)||r.length!==4||r.some(v=>typeof v!=="number"||!Number.isFinite(v)))throw new Error("a rectangle is four finite numbers: left, top, right, bottom");return r};
export function rectOverlaps(a,b){const[al,at,ar,ab]=rect(a),[bl,bt,br,bb]=rect(b);return!(ar<=bl||br<=al||ab<=bt||bb<=at)}
export function rectInside(inner,outer){const[il,it,ir,ib]=rect(inner),[ol,ot,or,ob]=rect(outer);return il>=ol&&it>=ot&&ir<=or&&ib<=ob}
export function rectDeflate(r,by){const[l,t,rr,b]=rect(r);return[l+by,t+by,rr-by,b-by]}
const center=([l,t,r,b])=>[l+(r-l)/2,t+(b-t)/2];
export function rectClampInside(r,viewport,padding=IRONY_PADDING){const[left,top,right,bottom]=rect(r),inset=rectDeflate(viewport,padding),[cx,cy]=center(inset),[rx,ry]=center([left,top,right,bottom]);let dx=0,dy=0;
 if(right-left>=inset[2]-inset[0])dx=cx-rx;else{if(left<inset[0])dx=inset[0]-left;if(right>inset[2])dx=inset[2]-right}
 if(bottom-top>=inset[3]-inset[1])dy=cy-ry;else{if(top<inset[1])dy=inset[1]-top;if(bottom>inset[3])dy=inset[3]-bottom}
 return[left+dx,top+dy,right+dx,bottom+dy]}
export function ironyDrop(arena,card,handle){const width=Number(arena[0]),height=Number(arena[1]);if(!(Number.isFinite(width)&&Number.isFinite(height)))throw new Error("the arena size must be finite");
 const viewport=[0,0,width,height],none={action:"none",dx:0,dy:0};
 if(card===null)return none;if(!rectOverlaps(card,viewport))return{action:"spawn",dx:0,dy:0};
 if(handle===null||rectInside(handle,rectDeflate(viewport,IRONY_PADDING)))return none;
 const clamped=rectClampInside(handle,viewport,IRONY_PADDING),[cx,cy]=center(clamped),[hx,hy]=center(rect(handle));return{action:"snap",dx:cx-hx,dy:cy-hy}}
export function holdRepeat(button,fire){let timer=null,every=null,pointer=null,repeated=false;
 const stop=()=>{clearTimeout(timer);clearInterval(every);timer=every=null;pointer=null};
 button.addEventListener("pointerdown",e=>{if(button.disabled||pointer!==null||e.buttons!==1)return;pointer=e.pointerId;repeated=false;
  const end=ev=>{if(ev.pointerId!==pointer)return;window.removeEventListener("pointerup",end);window.removeEventListener("pointercancel",end);stop();setTimeout(()=>{repeated=false},0)};
  window.addEventListener("pointerup",end);window.addEventListener("pointercancel",end);
  timer=setTimeout(()=>{if(button.disabled||pointer===null)return;repeated=true;fire();every=setInterval(()=>{if(button.disabled){stop();return}repeated=true;fire()},HOLD_INTERVAL)},HOLD_DELAY)});
 button.addEventListener("click",()=>{if(button.disabled)return;if(repeated){repeated=false;return}fire()});
 button.addEventListener("contextmenu",e=>{if(pointer!==null||repeated)e.preventDefault()})}
export function bindPlayground(root=document){return[...root.querySelectorAll("[data-ui-play]")].map(box=>{
 const data=JSON.parse(box.dataset.play),$=s=>box.querySelector(s),ironies=data.ironies;
 let state=counterState(),shownBurst=0;
 const val=$("[data-counter-value]"),orbs=$("[data-counter-orbs]"),label=$("[data-counter-label]"),status=$("[data-counter-status]"),hist=$("[data-counter-history]"),
  inc=$("[data-counter-increment]"),dec=$("[data-counter-decrement]"),reset=$("[data-counter-reset]"),undo=$("[data-counter-undo]"),radios=[...box.querySelectorAll('input[name="counter-step"]')];
 const render=()=>{const e=counterEffect(state.counter);val.textContent=String(state.counter);orbs.textContent=e.orbs.join(" ");orbs.dataset.kind=e.idle?"idle":e.heal?"heal":"damage";
  label.textContent=counterLabel(state.counter);status.textContent=data.status[counterStatusKey(state.counter)];
  radios.forEach(r=>{r.checked=Number(r.value)===state.step});inc.disabled=state.counter>=COUNTER_MAX;dec.disabled=state.counter<=COUNTER_MIN;reset.disabled=state.counter===0;undo.disabled=state.history.length<2;
  hist.replaceChildren(...state.history.map((v,i)=>{const li=document.createElement("li"),b=document.createElement("button");b.type="button";b.className="ui-button";b.textContent=String(v);
   if(i===0){b.disabled=true;b.setAttribute("aria-label","Current value "+v)}else{b.setAttribute("aria-label","Restore "+v);b.addEventListener("click",()=>act("restore",v))}li.append(b);return li}));
  box.dataset.value=String(state.counter);box.dataset.burst=String(state.burst);
  if(state.burst!==shownBurst){shownBurst=state.burst;orbs.removeAttribute("data-playing");if(!e.idle){void orbs.offsetWidth;orbs.setAttribute("data-playing","")}}};
 const act=(action,value)=>{state=counterApply(state,action,value);render()};
 holdRepeat(inc,()=>act("increment"));holdRepeat(dec,()=>act("decrement"));reset.addEventListener("click",()=>act("reset"));undo.addEventListener("click",()=>act("undo"));
 radios.forEach(r=>r.addEventListener("change",()=>{if(r.checked)act("step",Number(r.value))}));render();
 const arena=$("[data-irony-arena]"),card=$("[data-irony-card]"),handle=$("[data-irony-handle]"),text=$("[data-irony-text]"),tone=$("[data-irony-tone]"),next=$("[data-irony-next]");
 const seed=box.hasAttribute("data-play-seed")?Number(box.getAttribute("data-play-seed")):Math.floor(Math.random()*4294967296),rng=mulberry32(seed);
 let index=ironyFirst(ironies.length,rng()),ox=0,oy=0,drag=null;
 const show=()=>{text.textContent=ironies[index].text;tone.textContent=ironies[index].tone;arena.dataset.ironyIndex=String(index);card.style.setProperty("--ox",ox+"px");card.style.setProperty("--oy",oy+"px")};
 const spawn=()=>{const i=ironyNext(ironies.length,index,rng());if(i!==null)index=i;ox=oy=0;show();arena.removeAttribute("data-spawn");void arena.offsetWidth;arena.setAttribute("data-spawn","")};
 handle.addEventListener("pointerdown",e=>{if(drag||(e.pointerType==="mouse"&&e.button!==0))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};handle.setPointerCapture(e.pointerId);card.setAttribute("data-dragging","");e.preventDefault()});
 handle.addEventListener("pointermove",e=>{if(!drag||e.pointerId!==drag.id)return;ox+=e.clientX-drag.x;oy+=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;
  card.style.setProperty("--ox",ox+"px");card.style.setProperty("--oy",oy+"px")});
 const finish=e=>{if(!drag||e.pointerId!==drag.id)return;drag=null;
  const a=arena.getBoundingClientRect(),c=card.getBoundingClientRect(),h=handle.getBoundingClientRect(),rel=r=>[r.left-a.left,r.top-a.top,r.right-a.left,r.bottom-a.top];
  const r=ironyDrop([a.width,a.height],rel(c),rel(h));card.removeAttribute("data-dragging");
  if(r.action==="spawn")spawn();else{if(r.action==="snap"){ox+=r.dx;oy+=r.dy}show()}
  box.dispatchEvent(new CustomEvent("ui-irony-drop",{bubbles:true,detail:r}))};
 handle.addEventListener("pointerup",finish);handle.addEventListener("pointercancel",finish);
 next.addEventListener("click",spawn);show();box.dataset.play_ready="";return box})}
globalThis.webUiPlayground={COUNTER_MIN,COUNTER_MAX,COUNTER_STEPS,HOLD_DELAY,HOLD_INTERVAL,IRONY_PADDING,mulberry32,counterEffect,counterLabel,counterStatusKey,counterState,counterApply,holdRepeatCount,holdSwallowsClick,
 ironyFirst,ironyNext,ironySequence,rectOverlaps,rectInside,rectDeflate,rectClampInside,ironyDrop,holdRepeat,bindPlayground};
if(typeof document!=="undefined")bindPlayground();
</script></body></html>
', 'examples/test-report.html': '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test report</title><style>@layer base,components,theme;
/* css/tokens.css */
:root{--ui-bg:#0d1117;--ui-panel:#101820;--ui-fg:#d1f7c4;--ui-muted:#8b949e;--ui-border:#58a6ff;--ui-accent:#7ee787;--ui-danger:#cf222e;--ui-radius:0;--ui-space:1rem;--ui-max:960px;--ui-font:Meiryo,メイリオ,sans-serif;--ui-font-mono:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace}
/* Candidate themes, token-only: palettes, no theme files (see theme_palettes()). */
body[data-ui-theme="green"]{--ui-bg:#edf0ec;--ui-panel:#ffffff;--ui-fg:#163b3b;--ui-muted:#546a61;--ui-border:#ccdcd4;--ui-accent:#126d66;--ui-danger:#a73528;--ui-radius:.5rem;color-scheme:light}
body[data-ui-theme="red"]{--ui-bg:#f6eeee;--ui-panel:#fdfcfc;--ui-fg:#6c4141;--ui-muted:#7e6363;--ui-border:#d4bfbf;--ui-accent:#c43131;--ui-danger:#d02525;--ui-radius:.5rem;color-scheme:light}
body[data-ui-theme="blue"]{--ui-bg:#eef1f6;--ui-panel:#fcfcfd;--ui-fg:#41526c;--ui-muted:#636e7e;--ui-border:#bfc7d4;--ui-accent:#316cc4;--ui-danger:#d02525;--ui-radius:.5rem;color-scheme:light}
/* css/base.css */
@layer base{*{box-sizing:border-box}body{margin:0;background:var(--ui-bg);color:var(--ui-fg);font:16px/1.6 var(--ui-font)}pre,code,kbd,samp{font-family:var(--ui-font-mono)!important}.ui-page{max-width:var(--ui-max);margin:auto;padding:1.25rem}a{color:inherit}}
/* css/components.css */
@layer components{.ui-panel,.ui-card{background:var(--ui-panel);border:1px solid var(--ui-border);padding:1rem;margin:1rem 0;border-radius:var(--ui-radius)}.ui-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.75rem}.ui-tag{display:inline-block;border:1px solid var(--ui-border);padding:.1rem .4rem}.ui-button,.ui-input{font:inherit;background:var(--ui-panel);color:var(--ui-fg);border:1px solid var(--ui-border);padding:.6rem;border-radius:var(--ui-radius)}.ui-muted{color:var(--ui-muted)}.ui-output{font:inherit;white-space:pre-wrap;overflow:auto;background:#d8dee4;color:#161b22;border:1px solid #8c959f;border-radius:4px;padding:.75rem}pre code,.ui-output code{font-family:inherit;color:inherit}pre.ui-output code{background:transparent}@media(max-width:480px){.ui-page{padding:.75rem}.ui-grid{grid-template-columns:1fr}.ui-card,.ui-panel{margin:.75rem 0;padding:.75rem}}.ui-lightbox{border:1px solid var(--ui-border);background:var(--ui-panel);color:var(--ui-fg);padding:1rem;max-width:min(96vw,960px);max-height:96vh;border-radius:var(--ui-radius)}.ui-lightbox::backdrop{background:rgba(0,0,0,.72)}.ui-lightbox img{display:block;max-width:100%;max-height:calc(96vh - 8rem);margin:auto}.ui-lightbox-bar{display:flex;gap:.5rem;justify-content:space-between;margin-top:.75rem}body:has(.ui-lightbox[open]){overflow:hidden}}
/* css/coordinates.css */
@layer components{.ui-coord label{display:block;margin:8px 0 4px}.ui-coord .ui-input{width:100%;box-sizing:border-box}.ui-coord-bar{display:flex;flex-wrap:wrap;gap:8px 16px;margin:8px 0;padding:0;border:0}.ui-coord-bar label{display:inline-block;margin:0}.ui-coord dt{margin:16px 0 4px}.ui-coord dd{margin:0}.ui-coord dd pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}}
/* css/door.css */
@layer components{.ui-door label{display:block;margin:8px 0 4px}.ui-door-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.ui-door-row .ui-input{flex:1 1 256px;min-width:0}.ui-door>.ui-input{width:100%;box-sizing:border-box}.ui-door-path{margin:8px 0;padding-left:24px}.ui-door-path a{overflow-wrap:anywhere}}
/* css/imagestudio.css */
