', 'examples/mcp-lab.html': '<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MCP lab</title><style>@layer base,components,theme;
/* css/tokens.css */
