@layer components{.ui-screens h3{margin:24px 0 8px}.ui-screens-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;margin:8px 0}.ui-screens .ui-button,.ui-screens select,.ui-screens .ui-input{min-height:48px;box-sizing:border-box;max-width:100%}.ui-screens-bar .ui-input{width:auto;min-width:0}@media(max-width:480px){.ui-screens-bar{gap:4px 8px}}.ui-screens-stage{min-width:0;margin:16px 0}.ui-screens-stage input[type=search],.ui-screens-stage #screens-field{width:100%}.ui-screens-items,.ui-screens-list,.ui-screens-checks,.ui-screens-chips,.ui-screens-links,.ui-screens-grid,.ui-screens-reorder,.ui-screens-swap,.ui-screens-animated{list-style:none;margin:8px 0;padding:0}.ui-screens-items{display:grid;gap:8px}.ui-screens-items[data-mode=grid]{grid-template-columns:repeat(auto-fill,minmax(160px,1fr))}.ui-screens-item{display:grid;gap:8px;min-height:48px;text-decoration:none;color:inherit;overflow-wrap:anywhere}.ui-screens-emoji{font-size:24px}.ui-screens-chips{display:flex;flex-wrap:wrap;gap:8px}.ui-screens-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ui-screens-grid li{white-space:pre-line;text-align:center}.ui-screens-list li{display:flex;gap:16px;align-items:center;margin:8px 0}.ui-screens-avatar{display:inline-flex;align-items:center;justify-content:center;flex:none;width:40px;height:40px;border-radius:50%;background:var(--ui-accent,currentColor);color:var(--ui-bg,Canvas)}.ui-screens-tabs,.ui-screens-bottom{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.ui-screens-tabs [aria-selected=true],.ui-screens-bottom [aria-current=page]{font-weight:700;text-decoration:underline}.ui-screens-dialog{margin:16px 0}.ui-screens code,.ui-screens-links li{overflow-wrap:anywhere}.ui-screens [data-screens-count]{display:block}.ui-screens pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;font-family:var(--ui-font-mono,monospace)}.ui-screens-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr