   h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0}
  H[0]+=a;H[1]+=b;H[2]+=c;H[3]+=d;H[4]+=e;H[5]+=f;H[6]+=g;H[7]+=h}
 const out=new Uint8Array(32),o=new DataView(out.buffer);H.forEach((x,i)=>o.setUint32(i*4,x));return out}
