/* page */
const digestOf=items=>sha256Hex(new TextEncoder().encode(pyJson(items))).slice(0,24);
const cursorEncode=(index,digest)=>btoa('{"v":1,"i":'+index+',"h":"'+digest+'"}').replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
